                    </div>
                    <div className="flex flex-col items-center">
                      <div className="w-48 h-px bg-slate-300 mb-4 law-signature-line" />
                      <p className="text-lg font-bold text-slate-900 leading-tight uppercase">
                        Luiz Akira Yoshio Otsubo
                      </p>
                      <p className="text-xs font-bold text-slate-500 uppercase tracking-tighter print:text-black">
                        1┬║ Secret├írio da CMTL
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              {/* PAPER FOOTER */}
              <div className="bg-slate-900 p-8 text-center text-white/50 space-y-2">
                <p className="text-[10px] font-bold uppercase tracking-widest">
                  SESMT SYSTEM - M├│dulo de Legisla├º├úo Municipal
                </p>
                <p className="text-[9px] font-medium opacity-50">
                  Documento gerado eletronicamente em conformidade com as leis
                  1562/99, 1599/00 e 3353/17.
                </p>
              </div>
            </div>

            {/* BACKGROUND ACCENT */}
            <div className="absolute -inset-4 bg-blue-600/5 blur-3xl rounded-none -z-10" />
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import {
  LayoutDashboard,
  Database,
  FileSearch,
  HeartPulse,
  LogOut,
  X,
  Menu,
  ClipboardList,
  Search,
  Save,
  ChevronLeft,
  Loader2,
  History as HistoryIcon,
  FolderOpen,
  TrendingUp,
  Scale,
  FileText,
} from "lucide-react";
import { Servidor } from "@/types";

export default function NewAbonoPage() {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [foundServidores, setFoundServidores] = useState<any[]>([]);
  const [selectedServidor, setSelectedServidor] = useState<Servidor | null>(
    null,
  );
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searching, setSearching] = useState(false);
  const [saving, setSaving] = useState(false);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [, setUserName] = useState<string>("Usu├írio");

  // Form data
  const [formData, setFormData] = useState({
    portaria: "",
    assomasul_numero: "",
    assomasul_data: "",
    inicio: "",
    quant: "12",
    observacoes: "",
    beneficiario_nome: "",
    renew_from_id: null as number | null,
  });

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (data.role === "analytic_manager") {
              alert(
                "Acesso Negado: Gerente Anal├¡tico n├úo possui permiss├úo para criar registros.",
              );
              router.push("/abono");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);

          // L├│gica de Renova├º├úo via URL Params
          const params = new URLSearchParams(window.location.search);
          const renewFrom = params.get("renew_from");
          const cpfParam = params.get("cpf");
          const beneficiarioParam = params.get("beneficiario");

          if (renewFrom && cpfParam) {
            setSearching(true);
            const cleanCpf = cpfParam.replace(/\D/g, "");
            const { data: servidor } = await supabase
              .from("servidores")
              .select("*")
              .or(`cpf.eq.${cleanCpf},cpf.eq.${cpfParam}`)
              .maybeSingle();

            if (servidor) {
              setSelectedServidor({
                Nome: servidor.nome,
                CPF: servidor.cpf,
                "CPF.": servidor.cpf,
                Cargo: servidor.cargo,
                Matr├¡cula: servidor.matricula,
                Secretaria: servidor.secretaria,
              });
              setFormData((prev) => ({
                ...prev,
                beneficiario_nome: beneficiarioParam || "",
                renew_from_id: parseInt(renewFrom),
              }));
            }
            setSearching(false);
          }
        } else {
          router.push("/login");
        }
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
  }, [router]);

  // Busca Autom├ítica (Autocomplete)
  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery.trim().length >= 3 && !selectedServidor) {
        performSearch(searchQuery);
      } else if (searchQuery.trim().length < 3) {
        setFoundServidores([]);
      }
    }, 400); // 400ms de delay para n├úo sobrecarregar o banco

    return () => clearTimeout(timer);
  }, [searchQuery]);

  const performSearch = async (queryStr: string) => {
    setSearching(true);
    const cleanQuery = queryStr.replace(/\D/g, "");
    const isNumeric = /^\d+$/.test(cleanQuery) && cleanQuery.length > 0;

    let query = supabase.from("servidores").select("*");

    if (isNumeric) {
      // Se for n├║mero, busca por CPF que COME├çA com esses n├║meros
      query = query.ilike("cpf", `${cleanQuery}%`).limit(8);
    } else {
      // Se for texto, busca por nome
      query = query.ilike("nome", `%${queryStr}%`).limit(8);
    }

    const { data, error } = await query;

    if (!error && data) {
      setFoundServidores(data);
    }
    setSearching(false);
  };

  const handleSearch = () => {
    if (searchQuery.trim()) {
      performSearch(searchQuery);
    }
  };

  const selectServidor = (s: any) => {
    setSelectedServidor({
      "CPF.": s.cpf,
      Nome: s.nome,
      Cargo: s.cargo,
      Matr├¡cula: s.matricula,
      "Dt.Nascimento": s.nascimento,
      Secretaria: s.secretaria,
      natureza_cargo: s.natureza_cargo,
      contrato: s.contrato,
    });
    setFoundServidores([]);
  };

  const handleSave = async () => {
    if (!selectedServidor) {
      alert("Selecione um servidor primeiro.");
      return;
    }

    if (!formData.inicio || !formData.portaria) {
      alert("Preencha os campos obrigat├│rios (Portaria e In├¡cio).");
      return;
    }

    setSaving(true);
    try {
      // 1. Inserir o novo Abono
      const rawCpf = (
        selectedServidor.CPF ||
        selectedServidor["CPF."] ||
        ""
      ).replace(/\D/g, "");
      const formattedCpf =
        rawCpf.length === 11
          ? `${rawCpf.slice(0, 3)}.${rawCpf.slice(3, 6)}.${rawCpf.slice(6, 9)}-${rawCpf.slice(9, 11)}`
          : selectedServidor.CPF || selectedServidor["CPF."] || "";

      const { data: newAbono, error } = await supabase
        .from("abono_salarial")
        .insert({
          cpf: formattedCpf,
          nome: selectedServidor.Nome,
          secretaria: selectedServidor.Secretaria,
          portaria: formData.portaria,
          assomasul_numero: formData.assomasul_numero || null,
          assomasul_data: formData.assomasul_data || null,
          inicio: formData.inicio,
          quant: 12,
          observacoes: formData.observacoes,
          beneficiario_nome:
            formData.beneficiario_nome.toUpperCase() || "PR├ôPRIO",
          natureza_cargo: selectedServidor.natureza_cargo || null,
          updated_at: new Date().toISOString(),
        })
        .select()
        .single();

      if (error) throw error;

      // 2. Se for uma renova├º├úo, vincular no registro antigo
      if (formData.renew_from_id && newAbono) {
        const { error: updateError } = await supabase
          .from("abono_salarial")
          .update({ renovado_por_id: newAbono.id })
          .eq("id", formData.renew_from_id);

        if (updateError)
          console.error("Erro ao vincular renova├º├úo:", updateError);
      }

      alert(
        formData.renew_from_id
          ? "Benef├¡cio renovado com sucesso!"
          : "Abono salarial registrado com sucesso!",
      );
      router.push("/abono");
    } catch (error: any) {
      console.error("Erro ao salvar abono:", error);
      alert("Erro ao salvar: " + error.message);
    } finally {
      setSaving(false);
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <aside
        className={`
                fixed lg:static inset-y-0 left-0 z-50 w-64 bg-[#1A3351] border-r border-white/10 flex flex-col p-4 shrink-0 shadow-2xl transition-transform duration-300 transform
                ${isSidebarOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"}
            `}
      >
        <div className="mb-8 flex flex-col items-center">
          <div className="flex justify-between items-center w-full lg:hidden mb-4">
            <span className="text-white font-bold text-xs uppercase">Menu</span>
            <button onClick={() => setIsSidebarOpen(false)}>
              <X className="w-6 h-6 text-white" />
            </button>
          </div>
          <div className="w-full h-16 mt-2 mb-4 flex items-center justify-center">
            <Image
              src="/images/logo_white.png"
              alt="SESMT"
              width={160}
              height={56}
              className="h-14 w-auto object-contain"
            />
          </div>
          <p className="text-[10px] font-bold text-white/40 uppercase tracking-[0.2em] -mt-2">
            SESMT SYSTEM
          </p>
        </div>

        <nav className="flex-1 space-y-1">
          <button
            onClick={() => router.push("/")}
            className="w-full flex items-center gap-1.5 p-3 rounded-none text-white/70 hover:bg-white/5 hover:text-white transition-all font-bold text-xs uppercase tracking-wider whitespace-nowrap"
          >
            <LayoutDashboard className="w-4 h-4 shrink-0" />
            <span>Criar documentos</span>
          </button>

          <button
            onClick={() => router.push("/referrals")}
            className="w-full flex items-center gap-1.5 p-3 rounded-none text-white/70 hover:bg-white/5 hover:text-white transition-all font-bold text-xs uppercase tracking-wider whitespace-nowrap"
          >
            <ClipboardList className="w-4 h-4 shrink-0" />
            <span>Central de Evid├¬ncias</span>
          </button>

          <div className="group">
            <button className="w-full flex items-center gap-1.5 p-3 rounded-none text-white/70 hover:bg-white/5 hover:text-white transition-all font-bold text-xs uppercase tracking-wider">
              <HeartPulse className="w-4 h-4 shrink-0" />
              <span>Benef├¡cios</span>
            </button>
            <button className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none text-white/60 hover:bg-white/5 hover:text-white transition-all font-bold text-[10px] uppercase tracking-wider whitespace-nowrap">
              <Database className="w-3.5 h-3.5 shrink-0" />
              <span>Aux├¡lio Doen├ºa</span>
            </button>
            <button className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none text-white/60 hover:bg-white/5 hover:text-white transition-all font-bold text-[10px] uppercase tracking-wider whitespace-nowrap">
              <FileSearch className="w-3.5 h-3.5 shrink-0" />
              <span>Readapta├º├úo</span>
            </button>
            <button
              onClick={() => router.push("/abono")}
              className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none bg-white/10 text-white font-bold text-[10px] uppercase tracking-wider whitespace-nowrap"
            >
              <ClipboardList className="w-3.5 h-3.5 shrink-0" />
              <span>Abono Salarial</span>
            </button>
            <button
              onClick={() => router.push("/abono/lei")}
              className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none text-white/60 hover:bg-white/5 hover:text-white transition-all font-bold text-[10px] uppercase tracking-wider whitespace-nowrap"
            >
              <Scale className="w-3.5 h-3.5 shrink-0" />
              <span>Legisla├º├úo e Regras</span>
            </button>
            <button
              onClick={() => router.push("/abono/portarias")}
              className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none text-white/60 hover:bg-white/5 hover:text-white transition-all font-bold text-[10px] uppercase tracking-wider whitespace-nowrap"
            >
              <FileText className="w-3.5 h-3.5 shrink-0" />
              <span>Portarias</span>
            </button>
            <button className="hidden group-hover:flex w-full items-center gap-1.5 p-2 pl-9 rounded-none text-white/60 hover:bg-white/5 hover:text-white transition-all font-bold text-[10px] uppercase tracking-wider whitespace-nowrap">
              <TrendingUp className="w-3.5 h-3.5 shrink-0" />
              <span>Redu├º├úo de Jornada</span>
            </button>
          </div>

          {(userRole === "admin" || userRole === "social_assistant") && (
            <>
              <div className="group">
                <button
                  onClick={() => router.push("/history")}
                  className="w-full flex items-center gap-1.5 p-3 rounded-none text-white/70 hover:bg-white/5 hover:text-white transition-all font-bold text-xs uppercase tracking-wider"
                >
                  <HistoryIcon className="w-4 h-4 shrink-0" />
                  <span>Hist├│rico</span>
                </button>
              </div>

              <button
                onClick={() => router.push("/archive")}
                className="w-full flex items-center gap-1.5 p-3 rounded-none text-white/70 hover:bg-white/5 hover:text-white transition-all font-bold text-xs uppercase tracking-wider"
              >
                <FolderOpen className="w-4 h-4 shrink-0" />
                <span>Arquivo M├®dico</span>
              </button>
            </>
          )}
        </nav>

        <div className="mt-auto space-y-4">
          <button
            onClick={handleLogout}
            className="w-full flex items-center gap-1.5 p-2 text-white/30 hover:text-white transition-all font-bold uppercase tracking-widest text-[10px] px-4"
          >
            <LogOut className="w-4 h-4" /> Sair
          </button>
        </div>
      </aside>

      {/* ├üREA PRINCIPAL */}
      <main className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible relative">
        {/* HEADER */}
        <section className="bg-[#B0B0B0] p-4 py-3 border-b-[6px] border-[#E31E24] shrink-0 shadow-lg">
          <div className="flex justify-between items-center mb-1">
            <div className="flex items-center gap-3">
              <button
                onClick={() => router.push("/abono")}
                className="p-2 hover:bg-black/5 rounded-none transition-colors"
              >
                <ChevronLeft className="w-6 h-6 text-[#1A3351]" />
              </button>
              <h2 className="text-xl font-bold leading-none uppercase tracking-tight text-[#1A3351]">
                Lan├ºamento de Abono Salarial
              </h2>
            </div>
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 bg-[#1A3351] rounded-none text-white active:scale-90 transition-transform"
            >
              <Menu className="w-6 h-6" />
            </button>
          </div>
        </section>

        <div className="flex-1 p-4 lg:p-8 overflow-y-auto">
          <div className="max-w-[1400px] mx-auto space-y-6">
            {/* BUSCAR SERVIDOR */}
            <div className="bg-white p-6 shadow-xl border-l-4 border-[#1A3351]">
              <h3 className="text-sm font-bold uppercase text-slate-400 mb-4 tracking-widest">
                Passo 1: Identificar Servidor
              </h3>
              <div className="flex gap-3">
                <input
                  type="text"
                  placeholder="NOME OU CPF DO SERVIDOR..."
                  className="flex-1 px-4 py-3 border border-[#888] shadow-inner text-base font-bold bg-[#E8E8E8] outline-none uppercase"
                  value={searchQuery}
                  onChange={(e) => {
                    setSearchQuery(e.target.value);
                    if (selectedServidor) setSelectedServidor(null);
                  }}
                  onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                />
                <button
                  onClick={handleSearch}
                  disabled={searching}
                  className="px-8 py-3 bg-[#1A3351] text-white font-bold uppercase text-sm rounded-none hover:brightness-110 active:scale-95 transition-all shadow-md flex items-center gap-2"
                >
                  {searching ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Search className="w-4 h-4" />
                  )}
                  Buscar
                </button>
              </div>

              {/* LISTA DE RESULTADOS (Autocomplete em tempo real) */}
              {foundServidores.length > 0 && !selectedServidor && (
                <div className="mt-2 border-2 border-[#1A3351] bg-white overflow-hidden rounded-none shadow-2xl animate-in fade-in slide-in-from-top-2 z-10 relative">
                  <div className="bg-[#1A3351] px-4 py-2 flex justify-between items-center">
                    <p className="text-[10px] font-bold text-white uppercase tracking-widest">
                      Sugest├Áes Encontradas
                    </p>
                    <button
                      onClick={() => setFoundServidores([])}
                      className="text-white hover:text-red-400"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="max-h-60 overflow-y-auto">
                    {foundServidores.map((s) => (
                      <button
                        key={s.id || s.cpf}
                        onClick={() => selectServidor(s)}
                        className="w-full text-left p-4 border-b border-slate-100 hover:bg-[#E31E24]/5 transition-colors group flex justify-between items-center"
                      >
                        <div>
                          <p className="text-sm font-bold text-[#1A3351] group-hover:text-[#E31E24] transition-colors uppercase">
                            {s.nome}
                          </p>
                          <div className="flex gap-4 mt-1">
                            <p className="text-[10px] font-bold text-slate-400 uppercase">
                              CPF: {s.cpf}
                            </p>
                          </div>
                        </div>
                        <div className="px-3 py-1 bg-slate-50 border border-slate-200 rounded-none text-[9px] font-bold text-[#1A3351] group-hover:bg-[#E31E24] group-hover:text-white group-hover:border-[#E31E24] transition-all uppercase">
                          Selecionar
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {selectedServidor && (
                <div className="mt-6 p-4 bg-slate-50 border border-slate-200 rounded-none grid grid-cols-2 gap-4 animate-in fade-in duration-300">
                  <div>
                    <p className="text-[11px] font-bold text-slate-400 uppercase">
                      Nome
                    </p>
                    <p className="text-xl font-bold uppercase text-[#1A3351]">
                      {selectedServidor.Nome}
                    </p>
                  </div>
                  <div>
                    <p className="text-[11px] font-bold text-slate-400 uppercase">
                      Cargo
                    </p>
                    <p className="font-bold uppercase text-sm text-[#1A3351]">
                      {selectedServidor.Cargo}
                    </p>
                  </div>
                  <div>
                    <p className="text-[11px] font-bold text-slate-400 uppercase">
                      Secretaria
                    </p>
                    <p className="font-bold uppercase text-sm text-[#1A3351]">
                      {selectedServidor.Secretaria}
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* DADOS DO ABONO */}
            {selectedServidor && (
              <div className="bg-white p-6 shadow-xl border-l-4 border-[#E31E24] animate-in slide-in-from-bottom-4 duration-500">
                <h3 className="text-sm font-bold uppercase text-slate-400 mb-6 tracking-widest">
                  Passo 2: Dados do Benef├¡cio
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      N├║mero da Portaria *
                    </label>
                    <input
                      type="text"
                      className="w-full px-4 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] uppercase text-lg text-[#1A3351]"
                      value={formData.portaria}
                      onChange={(e) =>
                        setFormData({ ...formData, portaria: e.target.value })
                      }
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      Benefici├írio / Dependente
                    </label>
                    <input
                      type="text"
                      placeholder="EX: PR├ôPRIO, FILHO 1, C├öNJUGE..."
                      className="w-full px-4 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] uppercase text-lg text-[#1A3351]"
                      value={formData.beneficiario_nome}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          beneficiario_nome: e.target.value,
                        })
                      }
                    />
                  </div>
                  {formData.renew_from_id && (
                    <div className="md:col-span-2 bg-amber-50 border-l-4 border-amber-500 p-4 mb-2 flex items-center gap-3">
                      <TrendingUp className="w-5 h-5 text-amber-600" />
                      <div>
                        <p className="text-[10px] font-bold text-amber-600 uppercase">
                          Aten├º├úo: Modo de Renova├º├úo
                        </p>
                        <p className="text-xs font-bold text-amber-800">
                          Este novo lan├ºamento dar├í continuidade ao benef├¡cio
                          selecionado.
                        </p>
                      </div>
                    </div>
                  )}
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      N├║mero Assomasul
                    </label>
                    <input
                      type="text"
                      placeholder="EX: 4041"
                      className="w-full px-4 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] uppercase text-lg text-[#1A3351]"
                      value={formData.assomasul_numero}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          assomasul_numero: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      Data Publica├º├úo Assomasul
                    </label>
                    <input
                      type="date"
                      className="w-full px-4 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] text-lg text-[#1A3351]"
                      value={formData.assomasul_data}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          assomasul_data: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      Data In├¡cio do Benef├¡cio *
                    </label>
                    <input
                      type="date"
                      className="w-full px-4 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] text-lg text-[#1A3351]"
                      value={formData.inicio}
                      onChange={(e) =>
                        setFormData({ ...formData, inicio: e.target.value })
                      }
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      Data de T├®rmino (Autom├ítico)
                    </label>
                    <div className="w-full px-4 py-3 border border-slate-200 rounded-none font-bold bg-slate-50 text-xl text-[#E31E24]">
                      {formData.inicio
                        ? (() => {
                            const date = new Date(
                              formData.inicio + "T00:00:00",
                            );
                            date.setFullYear(date.getFullYear() + 1);
                            return date.toLocaleDateString("pt-BR");
                          })()
                        : "---"}
                    </div>
                  </div>
                  <div className="md:col-span-2 space-y-1">
                    <label className="text-[11px] font-bold uppercase text-slate-600 pl-1">
                      Informa├º├Áes Adicionais / Observa├º├Áes
                    </label>
                    <textarea
                      rows={3}
                      placeholder="INSIRA AQUI OBSERVA├ç├òES RELEVANTES SOBRE ESTE BENEF├ìCIO..."
                      className="w-full px-4 py-4 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] outline-none focus:border-[#E31E24] uppercase text-base text-[#1A3351]"
                      value={formData.observacoes}
                      onChange={(e) =>
                        setFormData({
                          ...formData,
                          observacoes: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>

                <div className="mt-10 flex justify-end gap-4">
                  <button
                    onClick={() => router.push("/abono")}
                    className="px-6 py-3 text-[10px] font-bold uppercase text-slate-400 hover:text-slate-600 transition-all"
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={saving}
                    className="px-12 py-3 bg-[#E31E24] text-white font-bold uppercase text-sm rounded-none shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center gap-2 border-b-4 border-red-900"
                  >
                    {saving ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Save className="w-4 h-4" />
                    )}
                    Salvar Lan├ºamento
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect, use } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/layout/Sidebar";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import {
  Menu,
  Save,
  ChevronLeft,
  Loader2,
  User,
  Calendar,
  History as HistoryIcon,
  Eye,
  Download,
} from "lucide-react";
import { Servidor } from "@/types";
import { generatePortariaPDF, PortariaData } from "@/lib/portaria-pdf";
import { generatePortariaDOCX } from "@/lib/portaria-docx";
import { capitalizeName } from "@/lib/portaria-utils";

interface PortariaRecord {
  id: number;
  numero: number;
  ano: number;
  servidor_nome: string;
  servidor_cpf: string;
  servidor_matricula: string;
  servidor_cargo: string;
  servidor_lotacao: string;
  servidor_genero: "M" | "F";
  periodo_inicio: string;
  periodo_fim: string;
  data_portaria: string;
  servidor_contrato?: string;
  criado_por: string;
  criado_por_nome: string;
  created_at: string;
  motivo_alteracao?: string;
}

export default function EditPortariaPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const router = useRouter();
  const [selectedServidor, setSelectedServidor] = useState<Servidor | null>(
    null,
  );
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");
  const [, setMounted] = useState(false);
  const [originalData, setOriginalData] = useState<PortariaRecord | null>(null);
  const [changeLogs, setChangeLogs] = useState<any[]>([]);

  const [formData, setFormData] = useState({
    numero: "",
    periodo_inicio: "",
    periodo_fim: "",
    data_portaria: "",
    genero: "F" as "M" | "F",
    lotacao: "",
    motivo_alteracao: "",
  });

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (data.role === "analytic_manager") {
              alert(
                "Acesso Negado: Gerente Anal├¡tico n├úo possui permiss├úo para editar portarias.",
              );
              router.push("/abono/portarias");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);
          loadData();
        } else {
          router.push("/login");
        }
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
  }, [id, router]);

  const loadData = async () => {
    setLoading(true);
    try {
      // 1. Fetch Portaria Record
      const { data: portaria, error: portariaError } = await supabase
        .from("portarias_abono")
        .select("*")
        .eq("id", id)
        .single();

      if (portariaError || !portaria) {
        alert("Erro ao carregar registro de portaria.");
        router.push("/abono/portarias");
        return;
      }

      setFormData({
        numero: portaria.numero.toString(),
        periodo_inicio: portaria.periodo_inicio,
        periodo_fim: portaria.periodo_fim,
        data_portaria: portaria.data_portaria,
        genero: portaria.servidor_genero,
        lotacao: portaria.servidor_lotacao,
        motivo_alteracao: "",
      });
      setOriginalData(portaria);

      // Fetch Logs
      const { data: logs } = await supabase
        .from("portarias_abono_logs")
        .select("*")
        .eq("portaria_id", id)
        .order("data_alteracao", { ascending: false });
      if (logs) setChangeLogs(logs);

      // 2. Mock selected servidor for UI from portaria data
      setSelectedServidor({
        Nome: portaria.servidor_nome,
        Cargo: portaria.servidor_cargo,
        Matr├¡cula: portaria.servidor_matricula,
        Secretaria: "---", // Could fetch from servidores table but portaria has main info
        "CPF.": portaria.servidor_cpf,
        Sexo: portaria.servidor_genero,
        "Local de Trabalho": portaria.servidor_lotacao,
        contrato: portaria.servidor_contrato,
      });
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const formatDateBR = (dateStr: string) => {
    if (!dateStr) return "";
    const parts = dateStr.split("-");
    if (parts.length !== 3) return dateStr;
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  };

  const handlePreview = () => {
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert("Preencha todos os campos obrigat├│rios.");
      return;
    }
    const portariaData: PortariaData = {
      numero: parseInt(formData.numero),
      ano: originalData?.ano || new Date().getFullYear(),
      servidor_nome: selectedServidor?.Nome || "",
      servidor_matricula: selectedServidor?.Matr├¡cula || "",
      servidor_cargo: selectedServidor?.Cargo || "",
      servidor_lotacao: formData.lotacao,
      servidor_genero: formData.genero,
      periodo_inicio: formatDateBR(formData.periodo_inicio),
      periodo_fim: formatDateBR(formData.periodo_fim),
      data_portaria: formatDateBR(formData.data_portaria),
      servidor_contrato: selectedServidor?.contrato,
    };
    generatePortariaPDF(portariaData, "view");
  };

  const handleDownloadDOCX = async () => {
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert("Preencha todos os campos obrigat├│rios.");
      return;
    }
    const portariaData: PortariaData = {
      numero: parseInt(formData.numero),
      ano: originalData?.ano || new Date().getFullYear(),
      servidor_nome: selectedServidor?.Nome || "",
      servidor_matricula: selectedServidor?.Matr├¡cula || "",
      servidor_cargo: selectedServidor?.Cargo || "",
      servidor_lotacao: formData.lotacao,
      servidor_genero: formData.genero,
      periodo_inicio: formatDateBR(formData.periodo_inicio),
      periodo_fim: formatDateBR(formData.periodo_fim),
      data_portaria: formatDateBR(formData.data_portaria),
      servidor_contrato: selectedServidor?.contrato,
    };
    await generatePortariaDOCX(portariaData);
  };

  const handleUpdate = async () => {
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert(
        "Preencha os campos obrigat├│rios (N├║mero, Per├¡odo In├¡cio e Per├¡odo Fim).",
      );
      return;
    }

    if (!formData.motivo_alteracao || formData.motivo_alteracao.length < 5) {
      alert(
        "Para sua seguran├ºa, descreva o motivo desta altera├º├úo (m├¡nimo 5 caracteres).",
      );
      return;
    }

    setSaving(true);
    try {
      const { session } = await safeGetSession();
      const operatorName =
        session?.user?.email?.split("@")[0]?.toUpperCase() || "SISTEMA";

      // 1. Update record
      const { error: updateError } = await supabase
        .from("portarias_abono")
        .update({
          numero: parseInt(formData.numero),
          periodo_inicio: formData.periodo_inicio,
          periodo_fim: formData.periodo_fim,
          data_portaria: formData.data_portaria,
          servidor_lotacao: capitalizeName(formData.lotacao),
          servidor_genero: formData.genero,
          servidor_contrato: selectedServidor?.contrato,
          motivo_alteracao: formData.motivo_alteracao,
          alterado_por: operatorName,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id);

      if (updateError) throw updateError;

      // 2. Insert into audit logs
      const { error: logError } = await supabase
        .from("portarias_abono_logs")
        .insert({
          portaria_id: id,
          usuario_email: session?.user?.email || "desconhecido",
          motivo: formData.motivo_alteracao,
          dados_anteriores: originalData,
          dados_novos: {
            numero: parseInt(formData.numero),
            periodo_inicio: formData.periodo_inicio,
            periodo_fim: formData.periodo_fim,
            data_portaria: formData.data_portaria,
            servidor_lotacao: capitalizeName(formData.lotacao),
            servidor_genero: formData.genero,
            servidor_contrato: selectedServidor?.contrato,
          },
        });

      if (logError) console.error("Erro ao registrar log:", logError);

      alert("Portaria atualizada com sucesso!");
      router.push("/abono/portarias");
    } catch (error: any) {
      console.error("Erro ao atualizar portaria:", error);
      alert("Erro ao atualizar: " + error.message);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-full bg-[#D3D3D3] flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-12 h-12 text-[#E31E24] animate-spin" />
        <p className="text-[#1A3351] uppercase tracking-[0.3em] font-bold text-xs">
          Carregando dados...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <Sidebar
        userRole={userRole}
        userName={userName}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
      />

      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/60 z-40 lg:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* ├üREA PRINCIPAL */}
      <main className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible relative">
        {/* HEADER */}
        <section className="bg-[#B0B0B0] p-4 py-3 border-b-[6px] border-[#E31E24] shrink-0 shadow-lg">
          <div className="flex justify-between items-center mb-1">
            <div className="flex items-center gap-3">
              <button
                onClick={() => router.push("/abono/portarias")}
                className="p-2 hover:bg-black/5 rounded-none transition-colors"
              >
                <ChevronLeft className="w-6 h-6 text-[#1A3351]" />
              </button>
              <div>
                <h2 className="text-xl font-bold leading-none uppercase tracking-tight text-[#1A3351]">
                  Editar Portaria
                </h2>
                <p className="text-[9px] font-bold text-black/40 uppercase tracking-[0.2em] mt-1">
                  Ref: {id}
                </p>
              </div>
            </div>
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 bg-[#1A3351] rounded-none text-white active:scale-90 transition-transform"
            >
              <Menu className="w-6 h-6" />
            </button>
          </div>
        </section>

        <div className="flex-1 p-4 lg:p-8 overflow-y-auto font-sans">
          <div className="max-w-[1400px] mx-auto space-y-6">
            {/* SERVIDOR (BLOQUEADO) */}
            <div className="bg-white p-6 shadow-xl border-l-4 border-[#1A3351]">
              <h3 className="text-sm font-bold uppercase text-slate-400 mb-4 tracking-widest">
                Informa├º├Áes do Servidor
              </h3>
              {selectedServidor && (
                <div className="p-5 bg-slate-100 border border-slate-200 rounded-none grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-y-4 gap-x-8">
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
                      Nome Completo
                    </p>
                    <p className="text-lg font-bold uppercase text-[#1A3351] leading-tight">
                      {selectedServidor.Nome}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
                      CPF
                    </p>
                    <p className="text-sm font-bold text-slate-700">
                      {selectedServidor["CPF."]}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
                      Matr├¡cula
                    </p>
                    <div className="flex items-center gap-2">
                      <p className="text-sm font-bold text-slate-700">
                        {selectedServidor.Matr├¡cula}
                      </p>
                      {selectedServidor.contrato && (
                        <span className="bg-[#E31E24] text-white text-[9px] px-1.5 py-0.5 rounded-none font-bold uppercase">
                          Contrato {selectedServidor.contrato}
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="md:col-span-2">
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
                      Cargo
                    </p>
                    <p className="text-sm font-bold uppercase text-[#1A3351]">
                      {selectedServidor.Cargo}
                    </p>
                  </div>
                  <div>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">
                      Lota├º├úo Original
                    </p>
                    <p className="text-sm font-bold uppercase text-amber-600">
                      {selectedServidor["Local de Trabalho"] || "---"}
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* DADOS EDITAIS */}
            <div className="bg-white p-6 shadow-xl border-l-4 border-amber-500">
              <h3 className="text-sm font-bold uppercase text-slate-400 mb-6 tracking-widest text-left">
                Editar Dados da Portaria
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {/* N├║mero da Portaria */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase text-slate-600 pl-1">
                    N┬║ da Portaria *
                  </label>
                  <input
                    type="number"
                    className="w-full px-3 py-3 border border-slate-300 rounded-none font-bold bg-white uppercase text-xl text-[#1A3351] text-center focus:border-amber-500 outline-none"
                    value={formData.numero}
                    onChange={(e) =>
                      setFormData({ ...formData, numero: e.target.value })
                    }
                  />
                  <p className="text-[8px] font-bold text-amber-600 uppercase pl-1 leading-none text-left">
                    N┬║ {formData.numero || "---"}/SEGP/DGP/{originalData?.ano}
                  </p>
                </div>

                {/* Per├¡odo In├¡cio */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase text-slate-600 pl-1 text-left">
                    Per├¡odo In├¡cio *
                  </label>
                  <input
                    type="date"
                    className="w-full px-3 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] text-sm text-[#1A3351] focus:border-amber-500 outline-none"
                    value={formData.periodo_inicio}
                    onChange={(e) => {
                      const inicio = e.target.value;
                      if (inicio) {
                        const date = new Date(inicio + "T00:00:00");
                        if (!isNaN(date.getTime())) {
                          date.setFullYear(date.getFullYear() + 1);
                          const fimStr = date.toISOString().split("T")[0];
                          setFormData({
                            ...formData,
                            periodo_inicio: inicio,
                            periodo_fim: fimStr,
                          });
                        } else {
                          setFormData({
                            ...formData,
                            periodo_inicio: inicio,
                            periodo_fim: "",
                          });
                        }
                      } else {
                        setFormData({
                          ...formData,
                          periodo_inicio: inicio,
                          periodo_fim: "",
                        });
                      }
                    }}
                  />
                </div>

                {/* Per├¡odo Fim */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase text-slate-600 pl-1 text-left">
                    Per├¡odo Fim (Auto)
                  </label>
                  <input
                    type="date"
                    readOnly
                    className="w-full px-3 py-3 border border-slate-300 rounded-none font-bold bg-slate-100 text-sm text-[#1A3351] cursor-not-allowed"
                    value={formData.periodo_fim}
                  />
                </div>

                {/* Data Emiss├úo */}
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase text-slate-600 pl-1 text-left">
                    Data Emiss├úo
                  </label>
                  <input
                    type="date"
                    className="w-full px-3 py-3 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] text-sm text-[#1A3351] focus:border-amber-500 outline-none"
                    value={formData.data_portaria}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        data_portaria: e.target.value,
                      })
                    }
                  />
                </div>

                <div className="md:col-span-12">
                  <label className="text-[10px] font-bold uppercase text-slate-600 pl-1 text-left">
                    Lota├º├úo para o Documento
                  </label>
                  <input
                    type="text"
                    className="w-full px-3 py-3 border border-slate-300 rounded-none font-bold bg-white text-sm text-[#1A3351] focus:border-amber-500 outline-none uppercase"
                    value={formData.lotacao}
                    onChange={(e) =>
                      setFormData({ ...formData, lotacao: e.target.value })
                    }
                  />
                </div>

                {/* MOTIVO DA ALTERA├ç├âO */}
                <div className="md:col-span-2 space-y-1 bg-amber-50 p-4 rounded-none border border-amber-200">
                  <label className="text-[11px] font-bold uppercase text-amber-700 pl-1 flex items-center gap-2 mb-1">
                    <HistoryIcon className="w-4 h-4" /> Motivo da Altera├º├úo
                    (Obrigat├│rio)
                  </label>
                  <input
                    type="text"
                    placeholder="EX: CORRE├ç├âO DE DATA DE IN├ìCIO CONFORME SOLICITA├ç├âO"
                    className="w-full px-4 py-3 border border-amber-300 rounded-none font-bold bg-white outline-none focus:border-amber-500 uppercase text-xs text-[#1A3351]"
                    value={formData.motivo_alteracao}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        motivo_alteracao: e.target.value,
                      })
                    }
                  />
                </div>
              </div>

              {/* PREVIEW */}
              <div className="mt-8 p-4 bg-slate-50 border border-slate-200 rounded-none">
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-2 text-left">
                  Resumo da Vig├¬ncia
                </p>
                <div className="flex items-center gap-2">
                  <div className="bg-emerald-50 text-emerald-700 px-3 py-1 rounded-none border border-emerald-100 text-xs font-bold uppercase">
                    {formData.periodo_inicio
                      ? formatDateBR(formData.periodo_inicio)
                      : "---"}
                  </div>
                  <div className="h-px w-8 bg-slate-300" />
                  <div className="bg-red-50 text-red-700 px-3 py-1 rounded-none border border-red-100 text-xs font-bold uppercase">
                    {formData.periodo_fim
                      ? formatDateBR(formData.periodo_fim)
                      : "---"}
                  </div>
                </div>
              </div>

              <div className="mt-10 flex flex-col sm:flex-row justify-end gap-4">
                <button
                  onClick={() => router.push("/abono/portarias")}
                  className="px-6 py-3 text-[10px] font-bold uppercase text-slate-400 hover:text-slate-600 transition-all text-left"
                >
                  Cancelar
                </button>
                <button
                  onClick={handlePreview}
                  className="px-8 py-3 bg-[#1A3351] text-white font-bold uppercase text-[10px] lg:text-sm rounded-none shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  <Eye className="w-4 h-4" />
                  PDF
                </button>
                <button
                  onClick={handleDownloadDOCX}
                  className="px-8 py-3 bg-blue-600 text-white font-bold uppercase text-[10px] lg:text-sm rounded-none shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                >
                  <Download className="w-4 h-4" />
                  Word
                </button>
                <button
                  onClick={handleUpdate}
                  disabled={saving}
                  className="px-12 py-3 bg-green-600 text-white font-bold uppercase text-[10px] lg:text-sm rounded-none shadow-lg hover:bg-green-700 active:scale-95 transition-all flex items-center justify-center gap-2 border-b-4 border-green-800"
                >
                  {saving ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Save className="w-4 h-4" />
                  )}
                  Salvar Altera├º├Áes
                </button>
              </div>
            </div>

            {/* HIST├ôRICO DE AUDITORIA */}
            {changeLogs.length > 0 && (
              <div className="bg-white p-6 shadow-xl border-l-4 border-slate-400">
                <h3 className="text-sm font-bold uppercase text-slate-400 mb-6 tracking-widest flex items-center gap-2 text-left">
                  <HistoryIcon className="w-4 h-4" /> Trilha de Auditoria
                </h3>
                <div className="space-y-4">
                  {changeLogs.map((log: any) => (
                    <div
                      key={log.id}
                      className="text-[11px] p-4 bg-slate-50 rounded-none border border-slate-200"
                    >
                      <div className="flex justify-between font-bold uppercase text-slate-500 mb-2 border-b border-slate-200 pb-1">
                        <span className="flex items-center gap-1">
                          <User className="w-3 h-3" /> {log.usuario_email}
                        </span>
                        <span className="flex items-center gap-1">
                          <Calendar className="w-3 h-3" />{" "}
                          {new Date(log.data_alteracao).toLocaleString("pt-BR")}
                        </span>
                      </div>
                      <p className="font-bold text-[#1A3351] uppercase underline decoration-amber-500/50 mb-1">
                        Motivo:
                      </p>
                      <p className="font-bold text-slate-700 uppercase leading-relaxed">
                        {log.motivo}
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/layout/Sidebar";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import {
  X,
  Menu,
  Search,
  Save,
  ChevronLeft,
  Loader2,
  User,
  Eye,
  Download,
} from "lucide-react";
import { Servidor } from "@/types";
import { generatePortariaPDF, PortariaData } from "@/lib/portaria-pdf";
import { generatePortariaDOCX } from "@/lib/portaria-docx";
import { getLotadoGrammar, capitalizeName } from "@/lib/portaria-utils";

export default function NewPortariaPage() {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [foundServidores, setFoundServidores] = useState<any[]>([]);
  const [selectedServidor, setSelectedServidor] = useState<Servidor | null>(
    null,
  );
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searching, setSearching] = useState(false);
  const [saving, setSaving] = useState(false);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");
  const [, setMounted] = useState(false);

  const today = new Date();
  const todayStr = today.toISOString().split("T")[0];

  const [formData, setFormData] = useState({
    numero: "",
    periodo_inicio: "",
    periodo_fim: "",
    data_portaria: todayStr,
    genero: "F" as "M" | "F",
    lotacao: "",
  });

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (data.role === "analytic_manager") {
              alert(
                "Acesso Negado: Gerente Anal├¡tico n├úo possui permiss├úo para criar portarias.",
              );
              router.push("/abono/portarias");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);
        } else {
          router.push("/login");
        }
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
  }, [router]);

  // Busca Autom├ítica (Autocomplete)
  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery.trim().length >= 3 && !selectedServidor) {
        performSearch(searchQuery);
      } else if (searchQuery.trim().length < 3) {
        setFoundServidores([]);
      }
    }, 400);
    return () => clearTimeout(timer);
  }, [searchQuery, selectedServidor]);

  const performSearch = async (queryStr: string) => {
    setSearching(true);
    const cleanQuery = queryStr.replace(/\D/g, "");
    const isNumeric = /^\d+$/.test(cleanQuery) && cleanQuery.length > 0;

    let query = supabase.from("servidores").select("*");

    if (isNumeric) {
      query = query.ilike("cpf", `${cleanQuery}%`).limit(8);
    } else {
      query = query.ilike("nome", `%${queryStr}%`).limit(8);
    }

    const { data, error } = await query;

    if (!error && data) {
      setFoundServidores(data);
    }
    setSearching(false);
  };

  const handleSearch = () => {
    if (searchQuery.trim()) {
      performSearch(searchQuery);
    }
  };

  const selectServidor = (s: any) => {
    setSelectedServidor({
      "CPF.": s.cpf,
      Nome: s.nome,
      Cargo: s.cargo,
      Matr├¡cula: s.matricula,
      "Dt.Nascimento": s.nascimento,
      Secretaria: s.secretaria,
      // Adicionando os novos campos vindos do banco
      Sexo: s.sexo,
      "Local de Trabalho": s.local_trabalho,
      contrato: s.contrato,
    });
    setFormData((prev) => ({
      ...prev,
      lotacao: s.local_trabalho || s.secretaria || "",
      genero: s.sexo === "M" || s.sexo === "MASCULINO" ? "M" : "F",
    }));
    setFoundServidores([]);
  };

  const formatDateBR = (dateStr: string) => {
    if (!dateStr) return "";
    const parts = dateStr.split("-");
    if (parts.length !== 3) return dateStr;
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  };

  const handlePreview = () => {
    if (!selectedServidor) {
      alert("Selecione um servidor primeiro.");
      return;
    }
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert("Preencha todos os campos obrigat├│rios.");
      return;
    }
    const portariaData: PortariaData = {
      numero: parseInt(formData.numero),
      ano: new Date().getFullYear(),
      servidor_nome: selectedServidor.Nome || "",
      servidor_matricula: selectedServidor.Matr├¡cula || "",
      servidor_cargo: selectedServidor.Cargo || "",
      servidor_lotacao: formData.lotacao,
      servidor_genero: formData.genero,
      periodo_inicio: formatDateBR(formData.periodo_inicio),
      periodo_fim: formatDateBR(formData.periodo_fim),
      data_portaria: formatDateBR(formData.data_portaria),
      servidor_contrato: selectedServidor.contrato,
    };
    generatePortariaPDF(portariaData, "view");
  };

  const handleDownloadDOCX = async () => {
    if (!selectedServidor) {
      alert("Selecione um servidor primeiro.");
      return;
    }
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert("Preencha todos os campos obrigat├│rios.");
      return;
    }
    const portariaData: PortariaData = {
      numero: parseInt(formData.numero),
      ano: new Date().getFullYear(),
      servidor_nome: selectedServidor.Nome || "",
      servidor_matricula: selectedServidor.Matr├¡cula || "",
      servidor_cargo: selectedServidor.Cargo || "",
      servidor_lotacao: formData.lotacao,
      servidor_genero: formData.genero,
      periodo_inicio: formatDateBR(formData.periodo_inicio),
      periodo_fim: formatDateBR(formData.periodo_fim),
      data_portaria: formatDateBR(formData.data_portaria),
      servidor_contrato: selectedServidor.contrato,
    };
    await generatePortariaDOCX(portariaData);
  };

  const handleSave = async () => {
    if (!selectedServidor) {
      alert("Selecione um servidor primeiro.");
      return;
    }
    if (!formData.numero || !formData.periodo_inicio || !formData.periodo_fim) {
      alert(
        "Preencha os campos obrigat├│rios (N├║mero, Per├¡odo In├¡cio e Per├¡odo Fim).",
      );
      return;
    }

    setSaving(true);
    try {
      const { session } = await safeGetSession();
      const operatorName =
        session?.user?.email?.split("@")[0]?.toUpperCase() || "SISTEMA";

      const { error } = await supabase.from("portarias_abono").insert({
        numero: parseInt(formData.numero),
        ano: new Date().getFullYear(),
        servidor_nome: capitalizeName(selectedServidor.Nome || ""),
        servidor_cpf: selectedServidor.CPF || selectedServidor["CPF."],
        servidor_matricula: selectedServidor.Matr├¡cula,
        servidor_contrato: selectedServidor.contrato,
        servidor_cargo: capitalizeName(selectedServidor.Cargo || ""),
        servidor_lotacao: capitalizeName(formData.lotacao),
        servidor_genero: formData.genero,
        periodo_inicio: formData.periodo_inicio,
        periodo_fim: formData.periodo_fim,
        data_portaria: formData.data_portaria,
        criado_por: session?.user?.id,
        criado_por_nome: operatorName,
      });

      if (error) throw error;

      // Gerar PDF automaticamente
      const portariaData: PortariaData = {
        numero: parseInt(formData.numero),
        ano: new Date().getFullYear(),
        servidor_nome: selectedServidor.Nome || "",
        servidor_matricula: selectedServidor.Matr├¡cula || "",
        servidor_cargo: selectedServidor.Cargo || "",
        servidor_lotacao: formData.lotacao,
        servidor_genero: formData.genero,
        periodo_inicio: formatDateBR(formData.periodo_inicio),
        periodo_fim: formatDateBR(formData.periodo_fim),
        data_portaria: formatDateBR(formData.data_portaria),
        servidor_contrato: selectedServidor.contrato,
      };
      generatePortariaPDF(portariaData, "view");

      alert("Portaria registrada com sucesso!");
      router.push("/abono/portarias");
    } catch (error: any) {
      console.error("Erro ao salvar portaria:", error);
      alert("Erro ao salvar: " + error.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <Sidebar
        userRole={userRole}
        userName={userName}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
      />

      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/60 z-40 lg:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* ├üREA PRINCIPAL */}
      <main className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible relative">
        {/* HEADER */}
        <section className="bg-[#B0B0B0] p-4 py-3 border-b-[6px] border-[#E31E24] shrink-0 shadow-lg">
          <div className="flex justify-between items-center mb-1">
            <div className="flex items-center gap-3">
              <button
                onClick={() => router.push("/abono/portarias")}
                className="p-2 hover:bg-black/5 rounded-none transition-colors"
              >
                <ChevronLeft className="w-6 h-6 text-[#1A3351]" />
              </button>
              <div>
                <h2 className="text-xl font-bold leading-none uppercase tracking-tight text-[#1A3351]">
                  Nova Portaria
                </h2>
                <p className="text-[9px] font-bold text-black/40 uppercase tracking-[0.2em] mt-1">
                  Cria├º├úo de Portaria de Abono Salarial
                </p>
              </div>
            </div>
            <button
              onClick={() => setIsSidebarOpen(true)}
              className="lg:hidden p-2 bg-[#1A3351] rounded-none text-white active:scale-90 transition-transform"
            >
              <Menu className="w-6 h-6" />
            </button>
          </div>
        </section>

        <div className="flex-1 p-4 lg:p-8 overflow-y-auto">
          <div className="max-w-[1400px] mx-auto space-y-6">
            {/* BUSCAR SERVIDOR */}
            <div className="bg-white p-6 shadow-xl border-l-4 border-[#1A3351]">
              <h3 className="text-sm font-bold uppercase text-slate-400 mb-4 tracking-widest">
                Passo 1: Identificar Servidor
              </h3>
              <div className="flex gap-3">
                <input
                  type="text"
                  placeholder="NOME OU CPF DO SERVIDOR..."
                  className="flex-1 px-4 py-3 border border-[#888] shadow-inner text-base font-bold bg-[#E8E8E8] outline-none uppercase"
                  value={searchQuery}
                  onChange={(e) => {
                    setSearchQuery(e.target.value);
                    if (selectedServidor) setSelectedServidor(null);
                  }}
                  onKeyDown={(e) => e.key === "Enter" && handleSearch()}
                />
                <button
                  onClick={handleSearch}
                  disabled={searching}
                  className="px-8 py-3 bg-[#1A3351] text-white font-bold uppercase text-sm rounded-none hover:brightness-110 active:scale-95 transition-all shadow-md flex items-center gap-2"
                >
                  {searching ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Search className="w-4 h-4" />
                  )}
                  Buscar
                </button>
              </div>

              {/* LISTA DE RESULTADOS */}
              {foundServidores.length > 0 && !selectedServidor && (
                <div className="mt-2 border-2 border-[#1A3351] bg-white overflow-hidden rounded-none shadow-2xl animate-in fade-in slide-in-from-top-2 z-10 relative">
                  <div className="bg-[#1A3351] px-4 py-2 flex justify-between items-center">
                    <p className="text-[10px] font-bold text-white uppercase tracking-widest">
                      Sugest├Áes Encontradas
                    </p>
                    <button
                      onClick={() => setFoundServidores([])}
                      className="text-white hover:text-red-400"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                  <div className="max-h-60 overflow-y-auto">
                    {foundServidores.map((s) => (
                      <button
                        key={s.id || s.cpf}
                        onClick={() => selectServidor(s)}
                        className="w-full text-left p-4 border-b border-slate-100 hover:bg-[#E31E24]/5 transition-colors group flex justify-between items-center"
                      >
                        <div>
                          <p className="text-sm font-bold text-[#1A3351] group-hover:text-[#E31E24] transition-colors uppercase">
                            {s.nome}
                          </p>
                          <div className="flex gap-4 mt-1">
                            <p className="text-[10px] font-bold text-slate-400 uppercase">
                              CPF: {s.cpf}
                            </p>
                            <p className="text-[10px] font-bold text-amber-600 uppercase">
                              Matr├¡cula: {s.matricula}
                            </p>
                            {s.contrato && (
                              <p className="text-[10px] font-bold text-[#E31E24] uppercase">
                                Contrato: {s.contrato}
                              </p>
                            )}
                            <p className="text-[10px] font-bold text-slate-400 uppercase">
                              Cargo: {s.cargo}
                            </p>
                          </div>
                        </div>
                        <div className="px-3 py-1 bg-slate-50 border border-slate-200 rounded-none text-[9px] font-bold text-[#1A3351] group-hover:bg-[#E31E24] group-hover:text-white group-hover:border-[#E31E24] transition-all uppercase">
                          Selecionar
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}

              {selectedServidor && (
                <div className="mt-6 p-5 bg-white border-2 border-slate-200 rounded-none shadow-sm space-y-3 animate-in fade-in slide-in-from-top-2 duration-300">
                  <div className="flex items-center gap-4 pb-2 border-b border-slate-100">
                    <div className="w-12 h-12 bg-[#1A3351] rounded-none flex items-center justify-center text-white shrink-0">
                      <User className="w-6 h-6" />
                    </div>
                    <div className="flex-1">
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                        Servidor Selecionado
                      </p>
                      <p className="text-xl font-bold uppercase text-[#1A3351]">
                        {selectedServidor.Nome}
                      </p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-y-3 gap-x-6 pt-2 text-sm">
                    <div className="flex items-center gap-2 md:col-span-2">
                      <p className="text-[10px] font-bold text-slate-400 uppercase w-20 shrink-0">
                        Cargo:
                      </p>
                      <p className="font-bold uppercase text-[#1A3351]">
                        {selectedServidor.Cargo}
                      </p>
                    </div>
                    <div className="flex items-center gap-2 md:col-span-2">
                      <p className="text-[10px] font-bold text-slate-400 uppercase w-20 shrink-0">
                        Secretaria:
                      </p>
                      <p className="font-bold uppercase text-[#1A3351]">
                        {selectedServidor.Secretaria}
                      </p>
                    </div>
                    <div className="flex items-center gap-2 md:col-span-2">
                      <p className="text-[10px] font-bold text-slate-400 uppercase w-20 shrink-0">
                        Lota├º├úo:
                      </p>
                      <p className="font-bold uppercase text-[#1A3351]">
                        {selectedServidor["Local de Trabalho"] || "---"}
                      </p>
                    </div>
                    <div className="flex items-center gap-2">
                      <p className="text-[10px] font-bold text-slate-400 uppercase w-20 shrink-0">
                        Matr├¡cula:
                      </p>
                      <div className="flex items-center gap-2">
                        <p className="font-bold text-slate-700">
                          {selectedServidor.Matr├¡cula}
                        </p>
                        {selectedServidor.contrato && (
                          <span className="bg-[#E31E24] text-white text-[9px] px-1.5 py-0.5 rounded-none font-bold uppercase">
                            Contrato {selectedServidor.contrato}
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <p className="text-[10px] font-bold text-slate-400 uppercase w-20 shrink-0">
                        Sexo:
                      </p>
                      <p className="font-bold uppercase text-slate-700">
                        {selectedServidor.Sexo === "F"
                          ? "Feminino"
                          : "Masculino"}
                      </p>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* DADOS DA PORTARIA */}
            {selectedServidor && (
              <div className="bg-white p-6 shadow-xl border-l-4 border-amber-500 animate-in slide-in-from-bottom-4 duration-500">
                <h3 className="text-sm font-bold uppercase text-slate-400 mb-6 tracking-widest">
                  Passo 2: Dados da Portaria
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  {/* N├║mero da Portaria */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase text-slate-600 pl-1">
                      N┬║ da Portaria *
                    </label>
                    <input
                      type="number"
                      className="w-full px-3 py-2 border border-slate-300 rounded-none font-bold bg-white uppercase text-xl text-[#1A3351] text-center focus:border-amber-500 outline-none"
                      value={formData.numero}
                      onChange={(e) =>
                        setFormData({ ...formData, numero: e.target.value })
                      }
                    />
                    <p className="text-[8px] font-bold text-amber-600 uppercase pl-1 leading-none">
                      N┬║ {formData.numero || "---"}/SEGP/DGP/
                      {new Date().getFullYear()}
                    </p>
                  </div>

                  {/* Per├¡odo In├¡cio */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase text-slate-600 pl-1">
                      Per├¡odo In├¡cio *
                    </label>
                    <input
                      type="date"
                      className="w-full px-3 py-2 border border-slate-300 rounded-none font-bold bg-[#fcfcfc] text-sm text-[#1A3351]"
                      value={formData.periodo_inicio}
                      onChange={(e) => {
                        const inicio = e.target.value;
                        // Auto-calcular fim (+1 ano)
                        if (inicio) {
                          const date = new Date(inicio + "T00:00:00");
                          if (!isNaN(date.getTime())) {
                            date.setFullYear(date.getFullYear() + 1);
                            const fimStr = date.toISOString().split("T")[0];
                            setFormData({
                              ...formData,
                              periodo_inicio: inicio,
                              periodo_fim: fimStr,
                            });
                          } else {
                            setFormData({
                              ...formData,
                              periodo_inicio: inicio,
                              periodo_fim: "",
                            });
                          }
                        } else {
                          setFormData({
                            ...formData,
                            periodo_inicio: inicio,
                            periodo_fim: "",
                          });
                        }
                      }}
                    />
                  </div>

                  {/* Per├¡odo Fim */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase text-slate-600 pl-1">
                      Per├¡odo Fim *
                    </label>
                    <input
                      type="date"
                      readOnly
                      className="w-full px-3 py-2 border border-slate-300 rounded-none font-bold bg-slate-100 text-sm text-[#1A3351] cursor-not-allowed"
                      value={formData.periodo_fim}
                    />
                  </div>

                  {/* Data da Portaria */}
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase text-slate-600 pl-1">
                      Data Emiss├úo
                    </label>
                    <input
                      type="date"
                      readOnly
                      className="w-full px-3 py-2 border border-slate-300 rounded-none font-bold bg-slate-100 text-sm text-[#1A3351] cursor-not-allowed"
                      value={formData.data_portaria}
                    />
                  </div>

                  <div className="lg:col-span-12 flex items-center">
                    <div className="bg-emerald-50 border border-emerald-100 px-3 py-2 rounded-none w-full">
                      <p className="text-[8px] font-bold text-emerald-700 uppercase mb-0.5">
                        Vig├¬ncia Calculada
                      </p>
                      <p className="text-[10px] font-bold text-emerald-600 uppercase">
                        {formData.periodo_inicio && formData.periodo_fim
                          ? `${formatDateBR(formData.periodo_inicio)} at├® ${formatDateBR(formData.periodo_fim)}`
                          : "Defina a data inicial"}
                      </p>
                    </div>
                  </div>
                </div>

                {/* Barra de Preview */}
                <div className="mt-6 p-4 bg-amber-50 border border-amber-200 rounded-none">
                  <p className="text-[10px] font-bold text-amber-700 uppercase tracking-widest mb-2">
                    Pr├®via do Cabe├ºalho
                  </p>
                  <p className="text-sm font-bold text-[#1A3351] uppercase">
                    PORTARIA N┬║ {formData.numero || "---"}/SEGP/DGP/
                    {new Date().getFullYear()}
                  </p>
                  <p className="text-xs text-slate-600 mt-1 leading-relaxed">
                    ...
                    {formData.genero === "F"
                      ? "a servidora P├║blica Municipal"
                      : "o servidor P├║blico Municipal"}{" "}
                    <strong>{selectedServidor?.Nome}</strong>, matr├¡cula{" "}
                    {selectedServidor?.Matr├¡cula}, no cargo de{" "}
                    {selectedServidor?.Cargo},{" "}
                    {getLotadoGrammar(formData.genero, formData.lotacao)}{" "}
                    {formData.lotacao || "---"}.
                  </p>
                </div>

                <div className="mt-10 flex flex-col sm:flex-row justify-end gap-4">
                  <button
                    onClick={() => router.push("/abono/portarias")}
                    className="px-6 py-3 text-[10px] font-bold uppercase text-slate-400 hover:text-slate-600 transition-all"
                  >
                    Cancelar
                  </button>
                  <button
                    onClick={handlePreview}
                    className="px-8 py-3 bg-[#1A3351] text-white font-bold uppercase text-sm rounded-none shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <Eye className="w-4 h-4" />
                    PDF
                  </button>
                  <button
                    onClick={handleDownloadDOCX}
                    className="px-8 py-3 bg-blue-600 text-white font-bold uppercase text-sm rounded-none shadow-lg hover:brightness-110 active:scale-95 transition-all flex items-center justify-center gap-2"
                  >
                    <Download className="w-4 h-4" />
                    Word
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={saving}
                    className="px-12 py-3 bg-green-600 text-white font-bold uppercase text-sm rounded-none shadow-lg hover:bg-green-700 active:scale-95 transition-all flex items-center justify-center gap-2 border-b-4 border-green-800"
                  >
                    {saving ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <Save className="w-4 h-4" />
                    )}
                    Salvar e Gerar PDF
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo, useCallback } from "react";
import { supabase } from "@/lib/supabase";
import {
  Menu,
  ChevronDown,
  ChevronUp,
  History as HistoryIcon,
  Printer,
  Loader2,
  FileText,
  PlusCircle,
  Download,
  Eye,
  Building2,
  PencilLine,
} from "lucide-react";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/layout/Sidebar";
import CompactFilterBar from "@/components/filters/CompactFilterBar";
import FilterChips from "@/components/filters/FilterChips";
import ActionIconButton from "@/components/filters/ActionIconButton";
import {
  countActiveFilters,
  normalizeSearchTerm,
} from "@/components/filters/filtersUtils";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import { generatePortariaPDF, PortariaData } from "@/lib/portaria-pdf";

interface PortariaRecord {
  id: number;
  numero: number;
  ano: number;
  servidor_nome: string;
  servidor_cpf: string;
  servidor_matricula: string;
  servidor_cargo: string;
  servidor_lotacao: string;
  servidor_genero: "M" | "F";
  periodo_inicio: string;
  periodo_fim: string;
  data_portaria: string;
  servidor_contrato?: string;
  criado_por: string;
  criado_por_nome: string;
  created_at: string;
}

export default function PortariasPage() {
  const [records, setRecords] = useState<PortariaRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");
  const [, setMounted] = useState(false);
  const [sortOrder, setSortOrder] = useState("date-desc");
  const [logs, setLogs] = useState<Record<number, any[]>>({});

  useEffect(() => {
    setMounted(true);
  }, []);

  const loadLogs = useCallback(async () => {
    const { data: logsData } = await supabase
      .from("portarias_abono_logs")
      .select("*")
      .order("data_alteracao", { ascending: false });

    if (logsData) {
      const logsMap: Record<number, any[]> = {};
      logsData.forEach((log: any) => {
        if (!logsMap[log.portaria_id]) logsMap[log.portaria_id] = [];
        logsMap[log.portaria_id].push(log);
      });
      setLogs(logsMap);
    }
  }, []);

  const loadRecords = useCallback(async () => {
    setLoading(true);
    const { data, error } = await supabase
      .from("portarias_abono")
      .select("*")
      .order("numero", { ascending: false });

    if (!error && data) {
      setRecords(data);
      await loadLogs();
    } else if (error) {
      console.error("Erro ao carregar portarias:", error);
    }
    setLoading(false);
  }, [loadLogs]);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (
              data.role === "nurse" ||
              data.role === "operator" ||
              data.role === "viewer"
            ) {
              router.push("/");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);
        } else {
          router.push("/login");
          return;
        }
        loadRecords();
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event) => {
      if (event === "SIGNED_OUT") router.push("/login");
    });
    return () => subscription.unsubscribe();
  }, [router, loadRecords]);

  const clearAllFilters = () => {
    setSearchTerm("");
  };

  const headerActiveFilterCount = countActiveFilters({ searchTerm });

  const filteredRecords = useMemo(() => {
    return records.filter((r) => {
      const matchesSearch =
        r.servidor_nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.servidor_cpf.includes(searchTerm) ||
        r.numero.toString().includes(searchTerm);
      return matchesSearch;
    });
  }, [records, searchTerm]);

  const sortedRecords = useMemo(() => {
    const base = [...filteredRecords];
    if (sortOrder === "alpha") {
      return base.sort((a, b) =>
        a.servidor_nome.localeCompare(b.servidor_nome, "pt-BR"),
      );
    }
    if (sortOrder === "numero") {
      return base.sort((a, b) => b.numero - a.numero);
    }
    return base.sort(
      (a, b) =>
        new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
    );
  }, [filteredRecords, sortOrder]);

  const stats = useMemo(() => {
    const total = filteredRecords.length;
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();
    const thisMonth = filteredRecords.filter((r) => {
      const d = new Date(r.created_at);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    }).length;
    return { total, thisMonth };
  }, [filteredRecords]);

  const formatDate = (dateStr: string | null | undefined) => {
    if (!dateStr) return "---";
    try {
      const parts = dateStr.split("-");
      if (parts.length !== 3) return dateStr;
      return `${parts[2]}/${parts[1]}/${parts[0]}`;
    } catch {
      return dateStr;
    }
  };

  const formatDateTime = (dateStr: string | null | undefined) => {
    if (!dateStr) return "---";
    try {
      return new Date(dateStr).toLocaleString("pt-BR");
    } catch {
      return dateStr;
    }
  };

  const getDiff = (prev: any, next: any) => {
    if (!prev || !next) return null;
    const changes: string[] = [];

    // Mapeamento de chaves para labels amig├íveis
    // Inclu├¡mos varia├º├Áes para suportar logs antigos (lotacao/servidor_lotacao)
    const fieldMapping: Record<
      string,
      { label: string; formatter?: (val: any) => string }
    > = {
      numero: { label: "N├ÜMERO" },
      servidor_genero: {
        label: "G├èNERO",
        formatter: (val) =>
          val === "M" ? "Masculino" : val === "F" ? "Feminino" : val,
      },
      genero: {
        label: "G├èNERO",
        formatter: (val) =>
          val === "M" ? "Masculino" : val === "F" ? "Feminino" : val,
      }, // Suporte para logs antigos
      periodo_inicio: { label: "DATA IN├ìCIO", formatter: formatDate },
      periodo_fim: { label: "DATA FIM", formatter: formatDate },
      data_portaria: { label: "DATA EMISS├âO", formatter: formatDate },
      servidor_lotacao: { label: "LOTA├ç├âO" },
      lotacao: { label: "LOTA├ç├âO" }, // Suporte para logs antigos
    };

    // Para evitar duplicidade com aliases (como lotacao vs servidor_lotacao)
    // rastreamos quais labels j├í foram processadas
    const processedLabels = new Set<string>();

    // Chaves principais que queremos comparar
    const primaryKeys = [
      "numero",
      "servidor_genero",
      "periodo_inicio",
      "periodo_fim",
      "data_portaria",
      "servidor_lotacao",
    ];

    primaryKeys.forEach((key) => {
      const config = fieldMapping[key];
      if (!config) return;

      // Busca o valor anterior e o novo
      // Tenta a chave principal e tenta o alias se necess├írio
      let pValInput = prev[key];
      let nValInput = next[key];

      // Fallback para aliases em logs antigos
      if (key === "servidor_lotacao") {
        if (pValInput === undefined) pValInput = prev["lotacao"];
        if (nValInput === undefined) nValInput = next["lotacao"];
      }
      if (key === "servidor_genero") {
        if (pValInput === undefined) pValInput = prev["genero"];
        if (nValInput === undefined) nValInput = next["genero"];
      }

      const pVal = pValInput ?? "---";
      const nVal = nValInput ?? "---";

      // Se for igual (ou ambos nulos/indefinidos), n├úo registra mudan├ºa
      if (pVal === nVal) return;

      // Aplicar formatadores
      const formattedPrev = config.formatter ? config.formatter(pVal) : pVal;
      const formattedNext = config.formatter ? config.formatter(nVal) : nVal;

      // Se ap├│s formata├º├úo for igual, ignora (ex: datas em formatos diferentes mas mesmo valor)
      if (formattedPrev === formattedNext) return;

      changes.push(`${config.label}: "${formattedPrev}" Ô×× "${formattedNext}"`);
      processedLabels.add(config.label);
    });

    return changes;
  };

  const handleViewPDF = (record: PortariaRecord) => {
    const portariaData: PortariaData = {
      numero: record.numero,
      ano: record.ano,
      servidor_nome: record.servidor_nome,
      servidor_matricula: record.servidor_matricula,
      servidor_cargo: record.servidor_cargo,
      servidor_lotacao: record.servidor_lotacao,
      servidor_genero: record.servidor_genero,
      periodo_inicio: formatDate(record.periodo_inicio),
      periodo_fim: formatDate(record.periodo_fim),
      data_portaria: formatDate(record.data_portaria),
      servidor_contrato: record.servidor_contrato,
    };
    generatePortariaPDF(portariaData, "view");
  };

  const handleDownloadPDF = (record: PortariaRecord) => {
    const portariaData: PortariaData = {
      numero: record.numero,
      ano: record.ano,
      servidor_nome: record.servidor_nome,
      servidor_matricula: record.servidor_matricula,
      servidor_cargo: record.servidor_cargo,
      servidor_lotacao: record.servidor_lotacao,
      servidor_genero: record.servidor_genero,
      periodo_inicio: formatDate(record.periodo_inicio),
      periodo_fim: formatDate(record.periodo_fim),
      data_portaria: formatDate(record.data_portaria),
      servidor_contrato: record.servidor_contrato,
    };
    generatePortariaPDF(portariaData, "download");
  };

  const handleDownloadDOCX = async (record: PortariaRecord) => {
    const { generatePortariaDOCX } = await import("@/lib/portaria-docx");
    const portariaData: PortariaData = {
      numero: record.numero,
      ano: record.ano,
      servidor_nome: record.servidor_nome,
      servidor_matricula: record.servidor_matricula,
      servidor_cargo: record.servidor_cargo,
      servidor_lotacao: record.servidor_lotacao,
      servidor_genero: record.servidor_genero,
      periodo_inicio: formatDate(record.periodo_inicio),
      periodo_fim: formatDate(record.periodo_fim),
      data_portaria: formatDate(record.data_portaria),
      servidor_contrato: record.servidor_contrato,
    };
    await generatePortariaDOCX(portariaData);
  };

  if (loading) {
    return (
      <div className="h-screen w-full bg-[#D3D3D3] flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-12 h-12 text-[#E31E24] animate-spin" />
        <p className="text-[#1A3351] uppercase tracking-[0.3em] font-bold text-xs">
          Carregando Portarias...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <Sidebar
        userRole={userRole}
        userName={userName}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
      />

      {isSidebarOpen && (
        <div
          className="fixed inset-0 bg-black/60 z-40 lg:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        />
      )}

      {/* ├üREA PRINCIPAL */}
      <main className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible print:hidden">
        {/* HEADER */}
        <section className="bg-[#B0B0B0] p-4 lg:p-6 py-3 border-b-[6px] border-[#E31E24] shrink-0 shadow-lg font-sans">
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-3 shrink-0 text-[#1A3351]">
              <FileText className="w-5 lg:w-6 h-5 lg:h-6" />
              <div>
                <h2 className="text-base lg:text-lg font-bold leading-none uppercase tracking-tight">
                  Portarias
                </h2>
                <p className="text-[8px] font-bold text-black/40 uppercase tracking-[0.2em] mt-0.5 hidden sm:block">
                  Digital Ledger ÔÇó Portarias Oficiais
                </p>
              </div>
            </div>

            <div className="h-6 w-px bg-[#1A3351]/20 shrink-0 hidden sm:block" />

            <div className="flex-1 min-w-0">
              <CompactFilterBar
                searchTerm={searchTerm}
                setSearchTerm={setSearchTerm}
                startDate=""
                setStartDate={() => {}}
                endDate=""
                setEndDate={() => {}}
                isDateFilterOpen={false}
                setIsDateFilterOpen={() => {}}
                filterUser="all"
                setFilterUser={() => {}}
                filterSecretaria="all"
                setFilterSecretaria={() => {}}
                filterAsoType="all"
                setFilterAsoType={() => {}}
                uniqueUsersList={[]}
                uniqueSecretarias={[]}
                referrals={[]}
                operatorsMap={{}}
                clearAllFilters={clearAllFilters}
                searchPlaceholder="BUSCAR POR NOME, CPF OU N┬║ DA PORTARIA..."
                showUserFilter={false}
                showDateFilter={false}
                showSecretariaFilter={false}
                showAsoTypeFilter={false}
                activeFilterCount={headerActiveFilterCount}
              />
            </div>

            <div className="flex items-center gap-2 shrink-0">
              {userRole !== "analytic_manager" && (
                <ActionIconButton
                  className="hidden md:block"
                  icon={<PlusCircle className="w-4 h-4" />}
                  label="Nova portaria"
                  variant="success"
                  onClick={() => router.push("/abono/portarias/new")}
                />
              )}
              <button
                onClick={() => setIsSidebarOpen(true)}
                className="lg:hidden h-9 w-9 bg-[#1A3351] rounded-none text-white active:scale-95 transition-all shadow-md flex items-center justify-center"
              >
                <Menu className="w-4 h-4" />
              </button>
            </div>
          </div>

          <div className="mt-3">
            <FilterChips
              searchTerm={normalizeSearchTerm(searchTerm)}
              startDate=""
              endDate=""
              filterUser="all"
              filterSecretaria="all"
              filterAsoType="all"
              referrals={[]}
              operatorsMap={{}}
            />
          </div>
        </section>

        {/* CONTE├ÜDO */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6 lg:p-8 space-y-8">
          {/* STATS CARDS */}
          <div className="grid grid-cols-2 lg:grid-cols-3 gap-3 lg:gap-4 shrink-0">
            <div className="bg-white p-4 lg:p-6 border-l-4 border-[#1A3351] shadow-lg rounded-none lg:rounded-none transform hover:scale-[1.02] transition-all">
              <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-tight mb-1">
                Total de Portarias
              </p>
              <h3 className="text-xl lg:text-3xl font-bold text-[#1A3351]">
                {stats.total}
              </h3>
            </div>
            <div className="bg-white p-4 lg:p-6 border-l-4 border-emerald-500 shadow-lg rounded-none lg:rounded-none transform hover:scale-[1.02] transition-all">
              <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-tight mb-1">
                Emitidas no M├¬s
              </p>
              <h3 className="text-xl lg:text-3xl font-bold text-emerald-600">
                {stats.thisMonth}
              </h3>
            </div>
            <div className="bg-white p-4 lg:p-6 border-l-4 border-[#E31E24] shadow-lg rounded-none lg:rounded-none transform hover:scale-[1.02] transition-all col-span-2 lg:col-span-1">
              <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-tight mb-1">
                Sustentabilidade
              </p>
              <h3 className="text-xl lg:text-3xl font-bold text-[#E31E24]">
                {stats.total}{" "}
                <span className="text-xs font-normal">folhas digitais</span>
              </h3>
            </div>
          </div>

          {/* Mobile Button */}
          {userRole !== "analytic_manager" && (
            <button
              onClick={() => router.push("/abono/portarias/new")}
              className="md:hidden w-full flex items-center justify-center gap-2 px-6 py-3 bg-green-600 text-white font-bold rounded-none shadow-md hover:bg-green-700 active:scale-95 transition-all text-[10px] uppercase border border-black/10"
            >
              <PlusCircle className="w-4 h-4" />
              Nova Portaria
            </button>
          )}

          {/* LISTA */}
          <div className="bg-white border-2 border-slate-300 shadow-2xl overflow-hidden rounded-none">
            <div className="bg-[#B0B0B0] px-6 py-4 border-b-2 border-slate-400 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
              <div>
                <h3 className="text-sm font-bold uppercase tracking-widest text-[#1A3351]">
                  Registro Digital de Portarias
                </h3>
                <p className="text-[9px] font-bold text-slate-600 uppercase">
                  Portarias oficiais geradas via SESMT SYSTEM
                </p>
              </div>
              <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-end">
                <div className="flex items-center gap-2">
                  <span className="text-[10px] font-bold text-slate-600 uppercase">
                    Ordem:
                  </span>
                  <select
                    value={sortOrder}
                    onChange={(e) => setSortOrder(e.target.value)}
                    className="bg-[#D3D3D3] border border-slate-400 text-[10px] font-bold uppercase px-3 py-1.5 outline-none focus:border-[#1A3351]"
                  >
                    <option value="date-desc">Recentes Primeiro</option>
                    <option value="numero">N┬║ Portaria</option>
                    <option value="alpha">Ordem Alfab├®tica</option>
                  </select>
                </div>
                <div className="text-[10px] font-bold text-slate-700 uppercase bg-slate-200 px-3 py-1.5 border border-slate-300">
                  {sortedRecords.length} ITENS
                </div>
              </div>
            </div>

            <div className="divide-y divide-slate-100">
              {sortedRecords.length > 0 ? (
                sortedRecords.map((entry) => (
                  <div key={entry.id} className="group">
                    <div
                      onClick={() =>
                        setExpandedId(expandedId === entry.id ? null : entry.id)
                      }
                      className={`px-4 lg:px-8 py-4 flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4 lg:gap-6 hover:bg-slate-50 cursor-pointer transition-all border-l-[6px] ${expandedId === entry.id ? "bg-[#1A3351]/5 border-[#1A3351]" : "border-transparent"}`}
                    >
                      <div className="flex items-center gap-3 lg:gap-6 flex-1 w-full">
                        <div
                          className={`p-2 lg:p-2.5 rounded-none shadow-sm transition-all duration-300 shrink-0 ${expandedId === entry.id ? "bg-[#1A3351] text-white" : "bg-slate-100 text-slate-400"}`}
                        >
                          <FileText
                            className={`${expandedId === entry.id ? "w-5 lg:w-6 h-5 lg:h-6" : "w-4 lg:w-5 h-4 lg:h-5"}`}
                          />
                        </div>
                        <div className="flex flex-col min-w-0 flex-1">
                          <div className="flex items-baseline gap-2 lg:gap-4 overflow-hidden">
                            <h4
                              className={`font-bold uppercase text-[#1A3351] leading-none transition-all duration-300 truncate ${expandedId === entry.id ? "text-lg lg:text-xl" : "text-sm lg:text-base"}`}
                            >
                              {entry.servidor_nome}
                            </h4>
                            <span className="text-[8px] lg:text-[10px] font-bold text-amber-700 uppercase tracking-widest bg-amber-50 px-1.5 lg:px-2 py-0.5 border border-amber-200 shrink-0">
                              N┬║ {entry.numero}
                            </span>
                          </div>
                          <div className="flex gap-2 lg:gap-4 mt-1.5 lg:mt-2">
                            <span className="text-[8px] lg:text-[10px] font-bold text-[#1A3351] uppercase bg-blue-50 px-1.5 lg:px-2 py-0.5 border border-blue-100 truncate">
                              PORTARIA {entry.numero}/SEGP/DGP/{entry.ano}
                            </span>
                            <span className="text-[8px] lg:text-[10px] font-bold text-slate-500 uppercase flex items-center gap-1">
                              <Building2 className="w-3 h-3 shrink-0" />{" "}
                              {entry.servidor_lotacao || "---"}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div
                        className={`flex items-center justify-between lg:justify-end gap-4 lg:gap-8 w-full lg:w-auto shrink-0 transition-all ${expandedId === entry.id ? "opacity-100" : "opacity-70"}`}
                      >
                        <div className="flex flex-col">
                          <span className="font-bold text-[8px] lg:text-[9px] text-slate-400 uppercase mb-0.5 block tracking-widest">
                            Data
                          </span>
                          <span
                            className={`font-bold text-slate-800 transition-all ${expandedId === entry.id ? "text-sm lg:text-base" : "text-[10px] lg:text-xs"}`}
                          >
                            {formatDate(entry.data_portaria)}
                          </span>
                        </div>
                        {expandedId === entry.id ? (
                          <ChevronUp className="w-6 h-6 text-[#1A3351]" />
                        ) : (
                          <ChevronDown className="w-5 h-5 text-slate-300" />
                        )}
                      </div>
                    </div>

                    {/* DETALHES */}
                    {expandedId === entry.id && (
                      <div className="px-4 lg:px-8 pb-8 pt-4 bg-[#1A3351]/5 border-t border-slate-200 animate-in slide-in-from-top-4 duration-300">
                        <div className="grid grid-cols-1 md:grid-cols-12 gap-6 lg:gap-8 mt-2">
                          <div className="md:col-span-8 space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Servidor
                                </span>
                                <p className="text-xs lg:text-sm font-bold text-[#1A3351] uppercase leading-tight">
                                  {entry.servidor_nome}
                                </p>
                              </div>
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Matr├¡cula
                                </span>
                                <div className="flex items-center gap-2">
                                  <p className="text-xs lg:text-sm font-bold text-[#1A3351]">
                                    {entry.servidor_matricula}
                                  </p>
                                  {entry.servidor_contrato && (
                                    <span className="bg-[#E31E24] text-white text-[8px] px-1.5 py-0.5 rounded-none font-bold uppercase">
                                      Contrato {entry.servidor_contrato}
                                    </span>
                                  )}
                                </div>
                              </div>
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Cargo
                                </span>
                                <p className="text-xs lg:text-sm font-bold text-[#1A3351] uppercase leading-tight">
                                  {entry.servidor_cargo}
                                </p>
                              </div>
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Lota├º├úo
                                </span>
                                <p className="text-xs lg:text-sm font-bold text-[#1A3351] uppercase leading-tight">
                                  {entry.servidor_lotacao}
                                </p>
                              </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Per├¡odo In├¡cio
                                </span>
                                <p className="text-xs lg:text-sm font-bold text-emerald-600">
                                  {formatDate(entry.periodo_inicio)}
                                </p>
                              </div>
                              <div>
                                <span className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase mb-1 block border-b border-slate-200 pb-1">
                                  Per├¡odo Fim
                                </span>
                                <p className="text-xs lg:text-sm font-bold text-[#E31E24]">
                                  {formatDate(entry.periodo_fim)}
                                </p>
                              </div>
                            </div>
                          </div>

                          <div className="md:col-span-4 bg-white p-4 lg:p-5 border border-slate-200 shadow-inner rounded-none">
                            <span className="text-xs lg:text-sm font-bold text-[#1A3351] uppercase mb-3 block flex items-center gap-2 border-b border-slate-100 pb-2">
                              <FileText className="w-4 h-4 text-amber-500" />{" "}
                              Documento Oficial
                            </span>
                            <div className="space-y-1">
                              <p className="text-xs font-bold text-[#1A3351] uppercase tracking-tighter">
                                PORTARIA N┬║ {entry.numero}/SEGP/DGP/{entry.ano}
                              </p>
                              <p className="text-[10px] font-bold text-slate-500 uppercase">
                                Data Emiss├úo: {formatDate(entry.data_portaria)}
                              </p>
                            </div>
                          </div>

                          <div className="md:col-span-12 flex flex-col lg:flex-row justify-between items-stretch lg:items-center bg-slate-100/50 p-4 border border-slate-200 mt-2 gap-4 lg:gap-10 rounded-none">
                            <div className="flex flex-col lg:flex-row lg:items-center gap-4 lg:gap-10">
                              <div>
                                <span className="text-[8px] lg:text-[9px] font-bold text-slate-400 uppercase mb-0.5 block tracking-widest">
                                  Emitida por
                                </span>
                                <p className="text-[10px] lg:text-[11px] font-bold text-[#1A3351] uppercase">
                                  {entry.criado_por_nome || "SISTEMA"}
                                </p>
                              </div>
                              <div className="h-0.5 lg:h-8 w-full lg:w-px bg-slate-200" />
                              <div>
                                <span className="text-[8px] lg:text-[9px] font-bold text-slate-400 uppercase mb-0.5 block tracking-widest">
                                  Status
                                </span>
                                <p className="text-[10px] lg:text-[11px] font-bold text-[#28A745] uppercase flex items-center gap-1">
                                  Ô£ô REGISTRADA
                                </p>
                              </div>
                            </div>
                            <div className="px-4 py-2 bg-white border-2 border-[#1A3351] text-center shadow-sm">
                              <p className="text-[9px] lg:text-[10px] font-bold text-[#1A3351] uppercase leading-none">
                                REF: {entry.id}
                              </p>
                            </div>
                          </div>
                        </div>

                        <div className="mt-8 pt-4 border-t border-slate-200 flex flex-col lg:flex-row justify-between items-center gap-4">
                          <div className="flex flex-col lg:flex-row gap-3 w-full lg:w-auto">
                            <button
                              onClick={() => handleViewPDF(entry)}
                              className="w-full lg:w-auto px-6 py-3 lg:py-2 bg-[#1A3351] text-white text-[10px] font-bold uppercase hover:brightness-110 shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 rounded-none"
                            >
                              <Eye className="w-3.5 h-3.5" /> Visualizar PDF
                            </button>
                            <button
                              onClick={() => handleDownloadPDF(entry)}
                              className="w-full lg:w-auto px-6 py-3 lg:py-2 bg-[#1A3351] text-white text-[10px] font-bold uppercase hover:brightness-110 shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 rounded-none"
                            >
                              <Printer className="w-3.5 h-3.5" /> Baixar PDF
                            </button>
                            <button
                              onClick={() => handleDownloadDOCX(entry)}
                              className="w-full lg:w-auto px-6 py-3 lg:py-2 bg-[#2B579A] text-white text-[10px] font-bold uppercase hover:brightness-110 shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 rounded-none"
                            >
                              <Download className="w-3.5 h-3.5" /> Exportar Word
                            </button>
                            <button
                              onClick={() =>
                                router.push(`/abono/portarias/edit/${entry.id}`)
                              }
                              className="w-full lg:w-auto px-6 py-3 lg:py-2 bg-[#E31E24] text-white text-[10px] font-bold uppercase hover:brightness-110 shadow-lg active:scale-95 transition-all flex items-center justify-center gap-2 rounded-none"
                            >
                              <PencilLine className="w-3.5 h-3.5" /> Editar
                              Portaria
                            </button>
                          </div>
                          <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest truncate max-w-full">
                            Audit-Hash:{" "}
                            {Math.random()
                              .toString(36)
                              .substring(7)
                              .toUpperCase()}
                            -{entry.id}
                          </span>
                        </div>

                        {/* SE├ç├âO DE LOGS DE AUDITORIA */}
                        {logs[entry.id] && logs[entry.id].length > 0 && (
                          <div className="mt-8 pt-6 border-t border-slate-200">
                            <div className="flex items-center gap-2 mb-4">
                              <HistoryIcon className="w-4 h-4 text-slate-400" />
                              <h5 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                                Hist├│rico de Altera├º├Áes
                              </h5>
                            </div>
                            <div className="space-y-3">
                              {logs[entry.id].map((log) => {
                                const changes = getDiff(
                                  log.dados_anteriores,
                                  log.dados_novos,
                                );
                                return (
                                  <div
                                    key={log.id}
                                    className="bg-white border border-slate-200 p-3 rounded-none shadow-sm"
                                  >
                                    <div className="flex justify-between items-start mb-2">
                                      <div>
                                        <p className="text-[10px] font-bold text-[#1A3351] uppercase">
                                          Motivo: {log.motivo}
                                        </p>
                                        <p className="text-[9px] font-bold text-slate-400 uppercase mt-0.5">
                                          Por: {log.usuario_email} ÔÇó{" "}
                                          {formatDateTime(log.data_alteracao)}
                                        </p>
                                      </div>
                                    </div>
                                    {changes && changes.length > 0 && (
                                      <div className="bg-slate-50 p-2 rounded-none border border-slate-100 space-y-1">
                                        {changes.map((change, cIdx) => (
                                          <p
                                            key={cIdx}
                                            className="text-[9px] font-bold text-slate-600 flex items-center gap-2"
                                          >
                                            <span className="w-1 h-1 bg-amber-400 rounded-none" />
                                            {change}
                                          </p>
                                        ))}
                                      </div>
                                    )}
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                ))
              ) : (
                <div className="py-24 text-center flex flex-col items-center gap-4">
                  <FileText className="w-16 h-16 text-slate-200" />
                  <p className="text-slate-400 uppercase font-bold text-xs italic tracking-[0.3em]">
                    Nenhuma portaria registrada
                  </p>
                  {userRole !== "analytic_manager" && (
                    <button
                      onClick={() => router.push("/abono/portarias/new")}
                      className="mt-4 px-8 py-3 bg-green-600 text-white text-[10px] font-bold uppercase rounded-none shadow-lg hover:bg-green-700 active:scale-95 transition-all flex items-center gap-2"
                    >
                      <PlusCircle className="w-4 h-4" /> Criar Primeira Portaria
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="bg-[#B0B0B0] p-6 text-center border-2 border-slate-300 shadow-inner">
            <p className="text-[10px] font-bold uppercase tracking-[0.5em] text-slate-600">
              SESMT SYSTEM ÔÇö M├│dulo de Portarias Oficiais ÔÇö Powered by UXBRAS┬«
            </p>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter } from "next/navigation";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import {
  Activity,
  Save,
  ChevronLeft,
  Loader2,
  User,
  Plus,
  Trash2,
  CheckCircle2,
  Printer,
  Eye,
} from "lucide-react";
import Sidebar from "@/components/layout/Sidebar";
import {
  getCIDChapter,
  CIDDetails,
  searchCIDs,
  getCIDDetailsFromDB,
  normalizeCID,
} from "@/lib/cid-utils";
import { generateAfastamentoPDF } from "@/lib/afastamento-portaria-pdf";

interface Servidor {
  id?: number;
  cpf: string;
  nome: string;
  cargo: string;
  matricula: string;
  contrato: string;
  secretaria: string;
  natureza_cargo: string;
  sexo?: string; // M ou F
}

export default function NewAfastamentoPage() {
  const router = useRouter();
  const [searchQuery, setSearchQuery] = useState("");
  const [foundServidores, setFoundServidores] = useState<Servidor[]>([]);
  const [selectedServidor, setSelectedServidor] = useState<Servidor | null>(
    null,
  );
  const [allBonds, setAllBonds] = useState<Servidor[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [, setSearching] = useState(false);
  const [saving, setSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const [generatedPortaria, setGeneratedPortaria] = useState<any>(null);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");

  // Form data
  const [formData, setFormData] = useState({
    tipo_afastamento: "AUX. DOEN├çA",
    is_acidente_trabalho: false,
    data_inicio: "",
    data_fim: "",
    data_pericia: "",
    perito_nome: "",
    perito_crm: "",
    observacoes: "",
    renew_from_id: null as number | null,
  });

  const [selectedCids, setSelectedCids] = useState<CIDDetails[]>([]);
  const [cidInput, setCidInput] = useState("");
  const [foundCids, setFoundCids] = useState<CIDDetails[]>([]);
  const [searchingCids, setSearchingCids] = useState(false);
  const [diasAfastamento, setDiasAfastamento] = useState<string>("");

  const selectServidor = useCallback(
    async (s: Servidor) => {
      setSelectedServidor(s);

      // Se for homem, n├úo pode estar em Licen├ºa Maternidade
      const isMale = s.sexo === "M" || s.sexo === "MASCULINO";
      if (isMale && formData.tipo_afastamento === "LICEN├çA MATERNIDADE") {
        setFormData((prev) => ({ ...prev, tipo_afastamento: "AUX. DOEN├çA" }));
      }

      const { data: bonds } = await supabase
        .from("servidores")
        .select("*")
        .eq("cpf", s.cpf);
      if (bonds) setAllBonds(bonds);
      setFoundServidores([]);
    },
    [formData.tipo_afastamento],
  );

  const performSearch = useCallback(
    async (queryStr: string, autoSelectFirst = false) => {
      setSearching(true);
      const cleanQuery = queryStr.replace(/\D/g, "");
      const isNumeric = /^\d+$/.test(cleanQuery) && cleanQuery.length > 0;

      let query = supabase.from("servidores").select("*");
      if (isNumeric) {
        query = query.ilike("cpf", `${cleanQuery}%`);
      } else {
        query = query.ilike("nome", `%${queryStr}%`);
      }

      const { data, error } = await query.limit(10);

      if (!error && data) {
        setFoundServidores(data);
        // Auto-select: se s├│ houver 1 resultado, ou se vier de prorroga├º├úo (autoSelectFirst)
        if (data.length === 1 || (autoSelectFirst && data.length > 0)) {
          selectServidor(data[0]);
        }
      }
      setSearching(false);
    },
    [selectServidor],
  );

  // Debounce server search
  useEffect(() => {
    const timer = setTimeout(() => {
      if (searchQuery.length >= 3) {
        performSearch(searchQuery);
      } else {
        setFoundServidores([]);
      }
    }, 500);
    return () => clearTimeout(timer);
  }, [searchQuery, performSearch]);

  // Debounce CID search
  useEffect(() => {
    const timer = setTimeout(async () => {
      if (cidInput.trim().length >= 1) {
        setSearchingCids(true);
        const results = await searchCIDs(cidInput);
        setFoundCids(results);
        setSearchingCids(false);
      } else {
        setFoundCids([]);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [cidInput]);

  // Auto calculate data_fim
  useEffect(() => {
    if (formData.data_inicio && diasAfastamento) {
      const start = new Date(formData.data_inicio);
      const days = parseInt(diasAfastamento);
      if (!isNaN(days) && days > 0) {
        const end = new Date(start);
        end.setDate(start.getDate() + days - 1);
        setFormData((prev) => ({
          ...prev,
          data_fim: end.toISOString().split("T")[0],
        }));
      }
    }
  }, [formData.data_inicio, diasAfastamento]);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (data.role !== "admin" && data.role !== "nurse") {
              router.push("/afastamentos");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);

          // Check for extension (prorroga├º├úo)
          const params = new URLSearchParams(window.location.search);
          const renewFrom = params.get("renew_from");
          const cpf = params.get("cpf");
          if (renewFrom && cpf) {
            setFormData((prev) => ({
              ...prev,
              renew_from_id: parseInt(renewFrom),
            }));
            performSearch(cpf, true); // autoSelectFirst=true: seleciona mesmo com m├║ltiplos v├¡nculos
          }
        } else {
          router.push("/login");
        }
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
  }, [router, performSearch]);

  const addCid = async (cidToUse?: CIDDetails) => {
    if (cidToUse) {
      const alreadyExists = selectedCids.some((c) => c.code === cidToUse.code);
      if (!alreadyExists) {
        setSelectedCids([...selectedCids, cidToUse]);
      }
      setCidInput("");
      setFoundCids([]);
      return;
    }

    const normalizedInput = normalizeCID(cidInput);
    if (!normalizedInput) return;

    setSearchingCids(true);
    const details = await getCIDDetailsFromDB(normalizedInput);
    const alreadyExists = selectedCids.some((c) => c.code === details.code);
    if (!alreadyExists) {
      setSelectedCids([...selectedCids, details]);
    }
    setCidInput("");
    setFoundCids([]);
    setSearchingCids(false);
  };

  const removeCid = (index: number) => {
    setSelectedCids(selectedCids.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    if (!selectedServidor || allBonds.length === 0) {
      alert("Selecione um servidor primeiro.");
      return;
    }

    if (!formData.data_inicio || !formData.data_fim) {
      alert("Preencha a data de in├¡cio e a quantidade de dias.");
      return;
    }

    setSaving(true);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();

      // 1. Obter pr├│ximo n├║mero de portaria
      const currentYear = new Date().getFullYear();
      const { data: lastPortaria } = await supabase
        .from("portarias_afastamento")
        .select("numero")
        .eq("ano", currentYear)
        .order("numero", { ascending: false })
        .limit(1)
        .maybeSingle();

      const nextNumber = (lastPortaria?.numero || 0) + 1;

      // Se for prorroga├º├úo, vamos buscar os registros anteriores (siblings) para vincular corretamente
      let previousRecords: any[] = [];
      if (formData.renew_from_id) {
        const { data: baseRec } = await supabase
          .from("afastamentos")
          .select("*")
          .eq("id", formData.renew_from_id)
          .single();
        if (baseRec) {
          const { data: siblings } = await supabase
            .from("afastamentos")
            .select("*")
            .eq("servidor_cpf", baseRec.servidor_cpf)
            .eq("data_inicio", baseRec.data_inicio)
            .eq("data_fim", baseRec.data_fim)
            .eq("status", "ATIVO");
          if (siblings) previousRecords = siblings;
        }
      }

      // Lan├ºar para todos os v├¡nculos
      for (const bond of allBonds) {
        const { data: newAfastamento, error } = await supabase
          .from("afastamentos")
          .insert({
            servidor_cpf: bond.cpf,
            servidor_nome: bond.nome,
            servidor_matricula: bond.matricula,
            servidor_contrato: bond.contrato,
            servidor_secretaria: bond.secretaria,
            servidor_cargo: bond.cargo || bond.natureza_cargo,
            natureza_cargo: bond.natureza_cargo,
            tipo_afastamento: formData.tipo_afastamento,
            is_acidente_trabalho: formData.is_acidente_trabalho,
            data_inicio: formData.data_inicio,
            data_fim: formData.data_fim,
            data_pericia: formData.data_pericia || null,
            perito_nome: formData.perito_nome || null,
            perito_crm: formData.perito_crm || null,
            observacoes: formData.observacoes,
            situacao: "EM_ANDAMENTO",
            criado_por: user?.id || null,
            hash_auditoria: `AF-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`,
          })
          .select()
          .single();

        if (error) throw error;

        // Inserir CIDs
        for (const cid of selectedCids) {
          const chapter = getCIDChapter(cid.code);
          await supabase.from("afastamento_cids").insert({
            afastamento_id: newAfastamento.id,
            cid_codigo: cid.code,
            cid_descricao: cid.desc,
            cid_capitulo: chapter?.capitulo || "Desconhecido",
          });
        }

        // Gerar Registro de Portaria
        const { data: portariaRec } = await supabase
          .from("portarias_afastamento")
          .insert({
            afastamento_id: newAfastamento.id,
            numero: nextNumber,
            ano: currentYear,
            data_emissao: new Date().toISOString().split("T")[0],
            criado_por: user?.id || null,
          })
          .select()
          .single();

        // Para o PDF, vamos consolidar os v├¡nculos se houver mais de um
        const allContracts = allBonds.map((b) => b.contrato).join(" e ");

        setGeneratedPortaria({
          ...portariaRec,
          servidor_nome: bond.nome,
          servidor_matricula: bond.matricula,
          servidor_cargo: bond.cargo || bond.natureza_cargo,
          servidor_lotacao: bond.secretaria,
          data_inicio: new Date(formData.data_inicio).toLocaleDateString(
            "pt-BR",
          ),
          data_fim: new Date(formData.data_fim).toLocaleDateString("pt-BR"),
          tipo_afastamento: formData.tipo_afastamento,
          is_acidente_trabalho: formData.is_acidente_trabalho,
          perito_nome: formData.perito_nome,
          perito_crm: formData.perito_crm,
          servidor_contrato: allContracts, // <--- Joined contracts
        });

        // Prorroga├º├úo: Procurar o registro anterior correspondente a este v├¡nculo
        const prevBondRec = previousRecords.find(
          (pr) =>
            pr.servidor_matricula === bond.matricula &&
            pr.servidor_contrato === bond.contrato,
        );
        if (prevBondRec) {
          await supabase
            .from("afastamentos")
            .update({
              situacao: "PRORROGADO",
              renovado_por_id: newAfastamento.id,
            })
            .eq("id", prevBondRec.id);
        } else if (formData.renew_from_id && allBonds.length === 1) {
          // Fallback para caso simples de 1 v├¡nculo ou se a matr├¡cula mudou (raro)
          await supabase
            .from("afastamentos")
            .update({
              situacao: "PRORROGADO",
              renovado_por_id: newAfastamento.id,
            })
            .eq("id", formData.renew_from_id);
        }
      }

      setShowSuccess(true);
    } catch (err: any) {
      console.error(err);
      alert("Erro ao salvar: " + err.message);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black overflow-x-hidden">
