"use client";

import { useEffect, useState, useMemo } from "react";
import { supabase } from "@/lib/supabase";
import { Search, Printer, Loader2, FileText, Eye } from "lucide-react";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/layout/Sidebar";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";
import { generateAfastamentoPDF } from "@/lib/afastamento-portaria-pdf";

interface PortariaRecord {
  id: number;
  numero: number;
  ano: number;
  afastamento_id: number;
  data_emissao: string;
  created_at: string;
  // Joined fields
  servidor_nome: string;
  servidor_matricula: string;
  natureza_cargo: string;
  servidor_secretaria: string;
  tipo_afastamento: string;
  data_inicio: string;
  data_fim: string;
  perito_nome: string;
  perito_crm: string;
  servidor_contrato: string;
}

export default function AfastamentoPortariasPage() {
  const [records, setRecords] = useState<PortariaRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }
        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) {
            setUserRole(data.role);
            if (data.role !== "admin" && data.role !== "nurse") {
              router.push("/");
              return;
            }
          }
          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);
        } else {
          router.push("/login");
          return;
        }
        loadRecords();
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();
  }, [router]);

  async function loadRecords() {
    setLoading(true);
    // Joins with 'afastamentos' to get server details
    const { data, error } = await supabase
      .from("portarias_afastamento")
      .select(
        `
                *,
                afastamentos (
                    servidor_nome,
                    servidor_matricula,
                    natureza_cargo,
                    servidor_secretaria,
                    tipo_afastamento,
                    data_inicio,
                    data_fim,
                    perito_nome,
                    perito_crm,
                    servidor_contrato
                )
            `,
      )
      .order("numero", { ascending: false });

    if (!error && data) {
      const formatted: PortariaRecord[] = data.map((r: any) => ({
        ...r,
        servidor_nome: r.afastamentos.servidor_nome,
        servidor_matricula: r.afastamentos.servidor_matricula,
        natureza_cargo: r.afastamentos.natureza_cargo,
        servidor_secretaria: r.afastamentos.servidor_secretaria,
        tipo_afastamento: r.afastamentos.tipo_afastamento,
        data_inicio: r.afastamentos.data_inicio,
        data_fim: r.afastamentos.data_fim,
        perito_nome: r.afastamentos.perito_nome,
        perito_crm: r.afastamentos.perito_crm,
        servidor_contrato: r.afastamentos.servidor_contrato,
      }));
      setRecords(formatted);
    }
    setLoading(false);
  }

  const filteredRecords = useMemo(() => {
    return records.filter(
      (r: PortariaRecord) =>
        r.servidor_nome.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.numero.toString().includes(searchTerm),
    );
  }, [records, searchTerm]);

  const handleViewPDF = (record: PortariaRecord) => {
    generateAfastamentoPDF(
      {
        numero: record.numero,
        ano: record.ano,
        servidor_nome: record.servidor_nome,
        servidor_matricula: record.servidor_matricula,
        servidor_cargo: record.natureza_cargo,
        servidor_lotacao: record.servidor_secretaria,
        tipo_afastamento: record.tipo_afastamento,
        data_inicio: new Date(record.data_inicio).toLocaleDateString("pt-BR"),
        data_fim: new Date(record.data_fim).toLocaleDateString("pt-BR"),
        data_portaria: new Date(record.data_emissao).toLocaleDateString(
          "pt-BR",
        ),
        perito_nome: record.perito_nome,
        perito_crm: record.perito_crm,
        servidor_contrato: record.servidor_contrato,
      },
      "view",
    );
  };

  if (loading) {
    return (
      <div className="h-screen w-full bg-[#D3D3D3] flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-12 h-12 text-emerald-600 animate-spin" />
        <p className="text-[#1A3351] uppercase tracking-[0.3em] font-bold text-xs">
          Carregando Portarias...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black overflow-x-hidden">
      <Sidebar
        userRole={userRole}
        userName={userName}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
      />

      <main className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible">
        {/* HEADER */}
        <section className="bg-[#B0B0B0] p-4 lg:p-6 py-3 border-b-[6px] border-emerald-500 shrink-0 shadow-lg font-sans">
          <div className="flex justify-between items-center mb-3">
            <div className="flex items-center gap-3 text-[#1A3351]">
              <FileText className="w-6 h-6" />
              <h2 className="text-xl font-bold uppercase tracking-tight">
                Portarias de Afastamento
              </h2>
            </div>
            <button
              onClick={() => router.push("/afastamentos/new")}
              className="bg-emerald-600 text-white px-6 py-2 rounded-none font-bold text-[10px] uppercase shadow-md"
            >
              Nova Portaria
            </button>
          </div>

          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
            <input
              type="text"
              placeholder="BUSCAR POR NOME OU N┬║ DA PORTARIA..."
              className="w-full px-10 py-2.5 border border-[#888] shadow-inner text-sm font-bold bg-[#E8E8E8] outline-none uppercase"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </section>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
          <div className="bg-white border-2 border-slate-300 shadow-xl rounded-none overflow-visible">
            <div className="bg-[#B0B0B0] px-6 py-4 border-b-2 border-slate-400">
              <h3 className="text-sm font-bold uppercase text-[#1A3351]">
                Registro de Portarias Geradas
              </h3>
            </div>
            <div className="divide-y divide-slate-100">
              {filteredRecords.map((record: PortariaRecord) => (
                <div
                  key={record.id}
                  className="p-4 lg:px-8 hover:bg-slate-50 flex flex-col lg:flex-row justify-between items-center gap-4 transition-all"
                >
                  <div className="flex items-center gap-4">
                    <div className="p-2 bg-[#1A3351] text-white rounded-none">
                      <FileText className="w-5 h-5" />
                    </div>
                    <div>
                      <h4 className="font-bold text-[#1A3351] uppercase">
                        {record.servidor_nome}
                      </h4>
                      <p className="text-[10px] font-bold text-slate-500 uppercase">
                        Portaria N┬║ {record.numero}/{record.ano} ÔÇó{" "}
                        {record.tipo_afastamento}
                      </p>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={() => handleViewPDF(record)}
                      className="flex items-center gap-2 px-4 py-2 bg-[#1A3351] text-white text-[10px] font-bold uppercase rounded-none shadow hover:brightness-110"
                    >
                      <Eye className="w-3.5 h-3.5" /> Ver PDF
                    </button>
                    <button
                      onClick={() => {
                        generateAfastamentoPDF(
                          {
                            numero: record.numero,
                            ano: record.ano,
                            servidor_nome: record.servidor_nome,
                            servidor_matricula: record.servidor_matricula,
                            servidor_cargo: record.natureza_cargo,
                            servidor_lotacao: record.servidor_secretaria,
                            tipo_afastamento: record.tipo_afastamento,
                            data_inicio: new Date(
                              record.data_inicio,
                            ).toLocaleDateString("pt-BR"),
                            data_fim: new Date(
                              record.data_fim,
                            ).toLocaleDateString("pt-BR"),
                            data_portaria: new Date(
                              record.data_emissao,
                            ).toLocaleDateString("pt-BR"),
                            perito_nome: record.perito_nome,
                            perito_crm: record.perito_crm,
                            servidor_contrato: record.servidor_contrato,
                          },
                          "download",
                        );
                      }}
                      className="flex items-center gap-2 px-4 py-2 bg-emerald-600 text-white text-[10px] font-bold uppercase rounded-none shadow hover:brightness-110"
                    >
                      <Printer className="w-3.5 h-3.5" /> Baixar
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

"use client";

import { useEffect, useState, useMemo } from "react";
import { supabase } from "@/lib/supabase";
import {
  Menu,
  ChevronUp,
  ChevronDown,
  ClipboardList,
  Printer,
  Loader2,
  CreditCard,
  Activity,
} from "lucide-react";
import Sidebar from "@/components/layout/Sidebar";
import CompactFilterBar from "@/components/filters/CompactFilterBar";
import FilterChips from "@/components/filters/FilterChips";
import {
  type FilterState,
  matchesUnifiedNameCpfSearch,
  normalizeSearchTerm,
} from "@/components/filters/filtersUtils";
import { useRouter } from "next/navigation";
import { handleAuthError, safeGetSession } from "@/lib/auth-utils";

interface ReferralEntry {
  id: number;
  servidor_cpf: string;
  servidor_nome: string;
  aso_type: string;
  cargo?: string;
  secretaria?: string;
  ghe_conj?: string;
  function_name?: string;
  operator_name?: string;
  generated_at: string;
  generated_by: string;
  exams?: string[];
  risks?: string;
  exams_json?: any;
  servidor_nascimento?: string;
  contrato?: string;
}

export default function ReferralsPage() {
  const INITIAL_FILTERS: FilterState = {
    searchTerm: "",
    startDate: "",
    endDate: "",
    filterUser: "all",
    filterSecretaria: "all",
    filterAsoType: "all",
  };

  const [referrals, setReferrals] = useState<ReferralEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [filters, setFilters] = useState<FilterState>(INITIAL_FILTERS);
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState("");
  const [expandedId, setExpandedId] = useState<number | null>(null);
  const [userRole, setUserRole] = useState<string | null>(null);
  const [userName, setUserName] = useState<string>("Usu├írio");
  const [, setCurrentUserId] = useState<string | null>(null);
  const [isDateFilterOpen, setIsDateFilterOpen] = useState(false);

  // Smart Header Logic
  const [showHeader, setShowHeader] = useState(true);
  const [lastScrollTop, setLastScrollTop] = useState(0);
  const [scrollUpStart, setScrollUpStart] = useState(0);

  const handleMainScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const scrollTop = e.currentTarget.scrollTop;
    const isScrollingDown = scrollTop > lastScrollTop;

    if (isScrollingDown) {
      setScrollUpStart(scrollTop);
      if (scrollTop > 150 && showHeader) setShowHeader(false);
    } else {
      // S├│ mostra se subiu mais de 250px desde o ponto mais baixo ou chegou no topo
      if (scrollUpStart - scrollTop > 250 || scrollTop < 50) {
        if (!showHeader) setShowHeader(true);
      }
    }
    setLastScrollTop(scrollTop);
  };

  const [sortOrder, setSortOrder] = useState("date-desc");

  const setSearchTerm = (value: string) => {
    setFilters((prev) => ({ ...prev, searchTerm: value }));
  };
  const setStartDate = (value: string) => {
    setFilters((prev) => ({ ...prev, startDate: value }));
  };
  const setEndDate = (value: string) => {
    setFilters((prev) => ({ ...prev, endDate: value }));
  };
  const setFilterUser = (value: string) => {
    setFilters((prev) => ({ ...prev, filterUser: value }));
  };
  const setFilterSecretaria = (value: string) => {
    setFilters((prev) => ({ ...prev, filterSecretaria: value }));
  };
  const setFilterAsoType = (value: string) => {
    setFilters((prev) => ({ ...prev, filterAsoType: value }));
  };
  const clearAllFilters = () => {
    setFilters(INITIAL_FILTERS);
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearchTerm(filters.searchTerm);
    }, 180);

    return () => clearTimeout(timer);
  }, [filters.searchTerm]);

  useEffect(() => {
    const checkAuth = async () => {
      try {
        const { session, error } = await safeGetSession();
        if (error) {
          await handleAuthError(error);
          return;
        }

        if (session) {
          const { data } = await supabase
            .from("profiles")
            .select("role")
            .eq("id", session.user.id)
            .single();
          if (data) setUserRole(data.role);

          const name =
            session.user.user_metadata?.full_name ||
            session.user.email?.split("@")[0] ||
            "Usu├írio";
          setUserName(name);
          setCurrentUserId(session.user.id);
        } else {
          router.push("/login");
          return;
        }
        loadReferrals();
      } catch (err) {
        await handleAuthError(err);
      }
    };
    checkAuth();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event) => {
      if (event === "SIGNED_OUT") router.push("/login");
    });

    return () => subscription.unsubscribe();
  }, [router]);

  // Redirecionamento para perfis sem acesso
  useEffect(() => {
    if (userRole === "social_assistant") {
      router.push("/abono");
    } else if (userRole === "viewer") {
      router.push("/");
    }
  }, [userRole, router]);

  const [operatorsMap, setOperatorsMap] = useState<Record<string, string>>({});

  async function loadReferrals() {
    setLoading(true);

    // Carrega o hist├│rico apenas de encaminhamentos
    const { data: histData, error: histError } = await supabase
      .from("aso_history")
      .select("*")
      .ilike("aso_type", "%Encaminhamento%")
      .order("generated_at", { ascending: false });

    if (!histError && histData) {
      setReferrals(histData);
    }

    // Carrega mapeamento de perfis
    const { data: profData } = await supabase
      .from("profiles")
      .select("id, email");

    if (profData) {
      const map: Record<string, string> = {};
      profData.forEach((p) => {
        map[p.id] = p.email;
      });
      setOperatorsMap(map);
    }

    setLoading(false);
  }

  const uniqueUsersList = useMemo(
    () => Array.from(new Set(referrals.map((h) => h.generated_by))),
    [referrals],
  );
  const uniqueSecretarias = useMemo(
    () =>
      Array.from(
        new Set(referrals.map((h) => h.secretaria).filter(Boolean)),
      ).sort() as string[],
    [referrals],
  );

  const filteredReferrals = referrals.filter((entry) => {
    const matchesSearch = matchesUnifiedNameCpfSearch(
      entry.servidor_nome,
      entry.servidor_cpf,
      debouncedSearchTerm,
    );
    const matchesUser =
      filters.filterUser === "all" || entry.generated_by === filters.filterUser;
    const matchesSecretaria =
      filters.filterSecretaria === "all" ||
      entry.secretaria === filters.filterSecretaria;
    const matchesAsoType =
      filters.filterAsoType === "all" ||
      entry.aso_type
        .toUpperCase()
        .includes(filters.filterAsoType.toUpperCase());

    // Filtro de Data
    const entryDate = new Date(entry.generated_at).toISOString().split("T")[0];
    const matchesStartDate =
      !filters.startDate || entryDate >= filters.startDate;
    const matchesEndDate = !filters.endDate || entryDate <= filters.endDate;

    return (
      matchesSearch &&
      matchesUser &&
      matchesSecretaria &&
      matchesAsoType &&
      matchesStartDate &&
      matchesEndDate
    );
  });

  const sortedReferrals = useMemo(() => {
    const base = [...filteredReferrals];
    if (sortOrder === "alpha") {
      return base.sort((a, b) =>
        (a.servidor_nome || "").localeCompare(b.servidor_nome || "", "pt-BR"),
      );
    }
    return base.sort(
      (a, b) =>
        new Date(b.generated_at).getTime() - new Date(a.generated_at).getTime(),
    );
  }, [filteredReferrals, sortOrder]);

  const stats = useMemo(() => {
    const total = filteredReferrals.length;
    const uniqueUsers = new Set(filteredReferrals.map((h) => h.generated_by))
      .size;
    return { total, uniqueUsers };
  }, [filteredReferrals]);

  if (loading) {
    return (
      <div className="h-screen w-full bg-[#D3D3D3] flex flex-col items-center justify-center gap-4">
        <Loader2 className="w-12 h-12 text-[#E31E24] animate-spin" />
        <p className="text-[#1A3351] uppercase tracking-[0.3em] font-bold text-xs">
          Acessando Central de Evid├¬ncias...
        </p>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col lg:flex-row bg-[#D3D3D3] text-black font-sans overflow-x-hidden">
      {/* SIDEBAR */}
      <Sidebar
        userRole={userRole}
        userName={userName}
        isSidebarOpen={isSidebarOpen}
        setIsSidebarOpen={setIsSidebarOpen}
      />

      {/* Overlay de Foco Progressivo */}
      {/* Overlay de Foco Progressivo - Agora com pointer-events-none para n├úo bloquear o scroll */}
      <div
        className={`fixed inset-0 z-[45] bg-black/20 backdrop-blur-[2px] transition-all duration-500 pointer-events-none ${expandedId ? "opacity-100" : "opacity-0"}`}
      />

      {/* ├üREA PRINCIPAL */}
      <main
        onClick={() => setExpandedId(null)}
        className="flex-1 flex flex-col bg-[#D3D3D3] min-h-screen lg:h-screen lg:overflow-visible relative"
      >
        <div className="flex-1 flex flex-col relative overflow-visible">
          {/* HEADER - Smart Dynamic Header com Colapso de Espa├ºo */}
          <div
            className={`grid transition-all duration-500 ease-in-out ${showHeader ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0 pointer-events-none"}`}
          >
            <div className="overflow-visible">
              {/* HEADER COMPACTO ÔÇö linha ├║nica: ├¡cone+t├¡tulo | busca | filtros | menu mobile */}
              <section
                className={`bg-[#B0B0B0] px-4 lg:px-6 py-3 border-b-[6px] border-[#E31E24] shrink-0 shadow-lg transition-all duration-500 ease-in-out transform ${showHeader ? "translate-y-0" : "-translate-y-1/2"}`}
              >
                <div className="flex items-center gap-3">
                  {/* T├¡tulo + subt├¡tulo */}
                  <div className="flex items-center gap-2 shrink-0">
                    <ClipboardList className="w-5 h-5 text-[#1A3351]" />
                    <div>
                      <h2 className="text-base font-bold leading-none uppercase tracking-tight text-[#1A3351]">
                        Evid├¬ncias
                      </h2>
                      <p className="text-[8px] font-bold text-black/40 uppercase tracking-[0.2em] mt-0.5 hidden sm:block">
                        Digital Ledger ÔÇó Audit
                      </p>
                    </div>
                  </div>

                  <div className="h-6 w-px bg-[#1A3351]/20 shrink-0 hidden sm:block" />

                  {/* Toolbar compacta de filtros (busca + ├¡cones) */}
                  <div className="flex-1 min-w-0">
                    <CompactFilterBar
                      searchTerm={filters.searchTerm}
                      setSearchTerm={setSearchTerm}
                      startDate={filters.startDate}
                      setStartDate={setStartDate}
                      endDate={filters.endDate}
                      setEndDate={setEndDate}
                      isDateFilterOpen={isDateFilterOpen}
                      setIsDateFilterOpen={setIsDateFilterOpen}
                      filterUser={filters.filterUser}
                      setFilterUser={setFilterUser}
                      filterSecretaria={filters.filterSecretaria}
                      setFilterSecretaria={setFilterSecretaria}
                      filterAsoType={filters.filterAsoType}
                      setFilterAsoType={setFilterAsoType}
                      uniqueUsersList={uniqueUsersList}
                      uniqueSecretarias={uniqueSecretarias}
                      referrals={referrals}
                      operatorsMap={operatorsMap}
                      clearAllFilters={clearAllFilters}
                    />
                  </div>

                  {/* Menu mobile */}
                  <button
                    onClick={() => setIsSidebarOpen(true)}
                    className="lg:hidden h-9 w-9 bg-[#1A3351] rounded-none text-white active:scale-95 transition-all shadow-md flex items-center justify-center shrink-0"
                  >
                    <Menu className="w-4 h-4" />
                  </button>
                </div>

                {/* Chips de filtros ativos ÔÇö s├│ aparece quando h├í filtro */}
                <FilterChips
                  searchTerm={normalizeSearchTerm(filters.searchTerm)}
                  startDate={filters.startDate}
                  endDate={filters.endDate}
                  filterUser={filters.filterUser}
                  filterSecretaria={filters.filterSecretaria}
                  filterAsoType={filters.filterAsoType}
                  referrals={referrals}
                  operatorsMap={operatorsMap}
                />
              </section>
            </div>
          </div>

          {/* CONTE├ÜDO SCROLL├üVEL */}
          <div
            onScroll={handleMainScroll}
            className="flex-1 overflow-y-auto p-4 md:p-6 lg:p-10 space-y-8"
          >
            {/* STATS CARDS */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-6">
              <div className="bg-white p-4 lg:p-6 border-b-4 border-[#1A3351] shadow-md flex flex-col gap-1 rounded-none transform hover:translate-y-[-2px] transition-all">
                <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Registros
                </p>
                <h3 className="text-2xl lg:text-3xl font-bold text-[#1A3351]">
                  {stats.total}{" "}
                  <span className="text-[10px] lg:text-xs font-medium">
                    itens
                  </span>
                </h3>
              </div>
              <div className="bg-white p-4 lg:p-6 border-b-4 border-[#E31E24] shadow-md flex flex-col gap-1 rounded-none transform hover:translate-y-[-2px] transition-all">
                <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Sustentabilidade
                </p>
                <h3 className="text-2xl lg:text-3xl font-bold text-[#E31E24]">
                  {stats.total}{" "}
                  <span className="text-[10px] lg:text-xs font-medium">
                    folhas
                  </span>
                </h3>
              </div>
              <div className="bg-white p-4 lg:p-6 border-b-4 border-slate-300 shadow-md flex flex-col gap-1 rounded-none transform hover:translate-y-[-2px] transition-all">
                <p className="text-[9px] lg:text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  Auditores
                </p>
                <h3 className="text-2xl lg:text-3xl font-bold text-[#1A3351]">
                  {stats.uniqueUsers}
                </h3>
              </div>
            </div>

            {/* LISTA DE REGISTROS (DIGITAL LEDGER) */}
            <div className="bg-white border-2 border-slate-300 shadow-2xl overflow-visible rounded-none">
              <div className="bg-[#B0B0B0] px-6 py-4 border-b-2 border-slate-400 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                  <h3 className="text-sm font-bold uppercase tracking-widest text-[#1A3351]">
                    Registro Digital de Emiss├Áes
                  </h3>
                  <p className="text-[9px] font-bold text-slate-600 uppercase">
                    Evid├¬ncias oficiais geradas via SESMT SYSTEM
                  </p>
                </div>
                <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-end">
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-slate-600 uppercase">
                      Ordem:
                    </span>
                    <select
                      value={sortOrder}
                      onChange={(e) => setSortOrder(e.target.value)}
                      className="h-9 bg-[#D3D3D3] border border-slate-400 text-[10px] font-bold uppercase px-3 outline-none focus:border-[#1A3351] rounded-none"
                    >
                      <option value="date-desc">Recentes Primeiro</option>
